public class SleeperSimulation {
    private volatile boolean asleep = false;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    public void countSomeSheep() {
        System.out.println("Counting lanterns...");
        // Simulation of tallying lanterns
        try {
            Thread.sleep(500); // Simulating some time taken to count
            if (Math.random() > 0.9) { // Randomly decide the traveler falls asleep
                asleep = true;
                System.out.println("Traveler has fallen asleep.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        SleeperSimulation sleeperSimulation = new SleeperSimulation();

        Runnable sleepTask = sleeperSimulation::tryToSleep;

        Thread thread1 = new Thread(sleepTask, "Thread-1");
        Thread thread2 = new Thread(sleepTask, "Thread-2");

        thread1.start();
        thread2.start();

        try {
            thread1.join();
            thread2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("End of simulation.");
    }
}

