}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class LanternTally {

    private volatile boolean asleep;

    public LanternTally() {
        this.asleep = false;
    }

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        System.out.println("Tallying a lantern...");
        // Simulate some time taken for the action
        try {
            Thread.sleep(500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void fallAsleep() {
        asleep = true;
    }

    public static void main(String[] args) {
        LanternTally traveler = new LanternTally();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(traveler::tryToSleep);

        executor.execute(() -> {
            try {
                Thread.sleep(5000); // Let traveler count some lanterns
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            traveler.fallAsleep(); // After some time, traveler falls asleep
        });

        executor.shutdown();
    }
}

