import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ScoutFireflyObservation {

    private volatile boolean asleep = false;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    public void countSomeSheep() {
        System.out.println("Observing fireflies...");
        // Simulate some time delay during observation
        try {
            Thread.sleep(500);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        asleep = Math.random() > 0.9; // Randomly decide if the scout falls asleep
    }

    public static void main(String[] args) {
        ScoutFireflyObservation scout = new ScoutFireflyObservation();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = scout::tryToSleep;
        Runnable task2 = scout::tryToSleep;

        executor.submit(task1);
        executor.submit(task2);

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicBoolean;

public class ScoutFireflies {

    private volatile boolean asleep = false;
    private final AtomicBoolean keepCounting = new AtomicBoolean(true);

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        System.out.println("Observing fireflies...");
        try {
            Thread.sleep(500);  // Simulate time taken to observe fireflies
            if (Math.random() > 0.95) { // Assume a 5% chance of falling asleep
                asleep = true;
                keepCounting.set(false);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        ScoutFireflies scout = new ScoutFireflies();
        ExecutorService executorService = Executors.newFixedThreadPool(2);

        Runnable observationTask = () -> {
            while (scout.keepCounting.get()) {
                scout.tryToSleep();
            }
        };

        executorService.submit(observationTask);
        executorService.submit(observationTask);

        executorService.shutdown();
    }
}

