import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ScoutFireflies {
    private volatile boolean asleep = false;

    public void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    private void countSomeSheep() {
        // Simulating observing fireflies
        System.out.println("Observing fireflies...");
        try {
            Thread.sleep(500); // Simulated delay
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void setAsleep(boolean asleep) {
        this.asleep = asleep;
    }

    public static void main(String[] args) {
        ScoutFireflies scout = new ScoutFireflies();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable sleepTask = new Runnable() {
            @Override
            public void run() {
                scout.tryToSleep();
            }
        };

        Runnable timerTask = new Runnable() {
            @Override
            public void run() {
                try {
                    Thread.sleep(3000); // Wait for 3 seconds
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                scout.setAsleep(true); // Attempt to fall asleep
                System.out.println("The scout has fallen asleep.");
            }
        };

        executor.execute(sleepTask);
        executor.execute(timerTask);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}
