import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class CosmicCats {

    private final Set<String> catIdentifiers;

    public CosmicCats(Set<String> identifiers) {
        this.catIdentifiers = Collections.unmodifiableSet(new HashSet<>(identifiers));
    }

    public boolean isCosmicCat(String identifier) {
        return catIdentifiers.contains(identifier);
    }

    public String displayCatIdentifiers() {
        StringBuilder display = new StringBuilder("Cosmic Cats: \n");
        for (String id : catIdentifiers) {
            display.append("- ").append(id).append("\n");
        }
        return display.toString();
    }

    public static void main(String[] args) {
        Set<String> initialSet = new HashSet<>();
        initialSet.add("Whiskers");
        initialSet.add("Paws");
        initialSet.add("Claw");

        CosmicCats cosmicCats = new CosmicCats(initialSet);

        ExecutorService executorService = Executors.newFixedThreadPool(2);
        try {
            Callable<Boolean> checkCatTask = () -> cosmicCats.isCosmicCat("Whiskers");
            Callable<String> displayIdsTask = cosmicCats::displayCatIdentifiers;

            Future<Boolean> isCat = executorService.submit(checkCatTask);
            Future<String> displayIds = executorService.submit(displayIdsTask);

            System.out.println("Is 'Whiskers' a Cosmic Cat? " + isCat.get());
            System.out.println(displayIds.get());
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executorService.shutdown();
        }
    }
}

