public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Point> positions;

    public DelegatingDeviceTracker(Map<String, Point> initialPositions) {
        this.positions = new ConcurrentHashMap<>(initialPositions);
    }

    public Point getPosition(String gadgetId) {
        return positions.get(gadgetId);
    }

    public boolean updatePosition(String gadgetId, Point newPosition) {
        if (!positions.containsKey(gadgetId)) {
            return false;
        }
        positions.put(gadgetId, newPosition);
        return true;
    }

    public Map<String, Point> getUnmodifiableLivePositions() {
        return Collections.unmodifiableMap(positions);
    }

    public Map<String, Point> getUnmodifiableSnapshotPositions() {
        return Collections.unmodifiableMap(new HashMap<>(positions));
    }

    public static void main(String[] args) {
        Map<String, Point> initialPositions = new HashMap<>();
        initialPositions.put("gadget1", new Point(1, 1));
        initialPositions.put("gadget2", new Point(2, 2));

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updateTask = () -> {
            tracker.updatePosition("gadget1", new Point(3, 3));
