        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Snapshot Positions at End: " + tracker.getUnmodifiableSnapshotPositions());
    }

