public class ParcelMover {
    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Locker locker1 = new Locker(20);
        Locker locker2 = new Locker(10);
        executor.submit(() -> moveParcels(locker1, locker2, 5, 2, TimeUnit.SECONDS));
        executor.submit(() -> moveParcels(locker2, locker1, 5, 2, TimeUnit.SECONDS));
        executor.shutdown();
    }

    static class Locker {
        private final ReentrantLock lock = new ReentrantLock();
        private final ParcelCount parcelCount;

        public Locker(int initialItems) {
            this.parcelCount = new ParcelCount(initialItems);
        }

        public boolean tryLock(long timeout, TimeUnit unit) throws InterruptedException {
            return lock.tryLock(timeout, unit);
        }

        public void unlock() {
            lock.unlock();
        }

        public ParcelCount getParcelCount() {
            return parcelCount;
        }
    }

    static class ParcelCount {
        private final AtomicInteger count;

        public ParcelCount(int initialCount) {
            this.count = new AtomicInteger(initialCount);
        }

        public int getCount() {
            return count.get();
        }

        public boolean decrement(int amount) {
            if (count.get() >= amount) {
                count.addAndGet(-amount);
                return true;
            } else {
                return false;
            }
        }

        public void increment(int amount) {
            count.addAndGet(amount);
        }
    }

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    public static boolean moveParcels(Locker source, Locker target, int quantity, long timeout, TimeUnit unit) {
        long fixedDelay = 100; // fixed delay in milliseconds
        long maxRandomDelay = 200; // max random delay in milliseconds
        Random random = new Random();

        long timeoutMillis = unit.toMillis(timeout);
        long endTime = System.currentTimeMillis() + timeoutMillis;
        boolean moved = false;

        while (System.currentTimeMillis() < endTime) {
            try {
                if (source.tryLock(timeoutMillis, TimeUnit.MILLISECONDS)) {
                    try {
                        if (target.tryLock(timeoutMillis, TimeUnit.MILLISECONDS)) {
                            try {
                                if (source.getParcelCount().decrement(quantity)) {
                                    target.getParcelCount().increment(quantity);
                                    moved = true;
                                } else {
                                    throw new NotEnoughItemsException("Not enough items in source locker.");
                                }
                            } finally {
                                target.unlock();
                            }
                        }
                    } finally {
                        source.unlock();
                    }
                }
            } catch (InterruptedException | NotEnoughItemsException e) {
                // Handle exception or interrupt
            }

            if (moved) {
                break;
            }

            long randomDelay = random.nextInt((int) maxRandomDelay);
            try {
                Thread.sleep(fixedDelay + randomDelay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        return moved;
    }
}

