public class ParcelMover {

    public static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    public class ParcelCount {
        private int count;

        public ParcelCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void setCount(int count) {
            this.count = count;
        }
    }

    public class Locker {
        private final ReentrantLock lock = new ReentrantLock();
        private final ParcelCount parcelCount;

        public Locker(int initialCount) {
            this.parcelCount = new ParcelCount(initialCount);
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public ParcelCount getParcelCount() {
            return parcelCount;
        }
    }

    public boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit unit)
            throws InterruptedException, NotEnoughItemsException {

        long fixedDelay = 50; 
        long randomDelay = (long) (Math.random() * 50); 
        long deadline = System.nanoTime() + unit.toNanos(timeout);

        while (System.nanoTime() < deadline) {
            if (source.getLock().tryLock(fixedDelay + randomDelay, TimeUnit.MILLISECONDS)) {
                try {
                    if (target.getLock().tryLock(fixedDelay + randomDelay, TimeUnit.MILLISECONDS)) {
                        try {
                            ParcelCount sourceCount = source.getParcelCount();
                            ParcelCount targetCount = target.getParcelCount();
                            if (sourceCount.getCount() < quantity) {
                                throw new NotEnoughItemsException("Not enough items in the source locker.");
                            }
                            sourceCount.setCount(sourceCount.getCount() - quantity);
                            targetCount.setCount(targetCount.getCount() + quantity);
                            return true;
                        } finally {
                            target.getLock().unlock();
                        }
                    }
                } finally {
                    source.getLock().unlock();
                }
            }
            Thread.sleep(fixedDelay + randomDelay);
        }
        return false;
    }

    public static void main(String[] args) {
        ParcelMover parcelMover = new ParcelMover();
        Locker locker1 = parcelMover.new Locker(10);
        Locker locker2 = parcelMover.new Locker(5);

        ExecutorService executor = Executors.newFixedThreadPool(2);

