public class ContainerSwapApp {
    public static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }

    public static class ElementCount {
        private final int count;

        public ElementCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }
    }

    public static class Container {
        private int elements;
        private final Lock lock = new ReentrantLock();

        public Container(int initialElements) {
            this.elements = initialElements;
        }

        public boolean tryLock(long timeout, TimeUnit unit) throws InterruptedException {
            return lock.tryLock(timeout, unit);
        }

        public void unlock() {
            lock.unlock();
        }

        public void addElements(int number) {
            this.elements += number;
        }

        public void removeElements(int number) throws InsufficientElementsException {
            if (this.elements >= number) {
                this.elements -= number;
            } else {
                throw new InsufficientElementsException("Insufficient elements in the container.");
            }
        }

        public int getElementCount() {
            return elements;
        }
    }

    public static class SwapTask implements Callable<Boolean> {
        private final Container origin;
        private final Container target;
        private final int elementsToSwap;
        private final long timeout;
        private final TimeUnit timeUnit;

        public SwapTask(Container origin, Container target, int elementsToSwap, long timeout, TimeUnit timeUnit) {
            this.origin = origin;
            this.target = target;
            this.elementsToSwap = elementsToSwap;
            this.timeout = timeout;
            this.timeUnit = timeUnit;
        }

        @Override
        public Boolean call() {
            Random random = new Random();
            long startTime = System.currentTimeMillis();
            while (System.currentTimeMillis() - startTime < timeUnit.toMillis(timeout)) {
                try {
                    if (origin.tryLock(random.nextInt(10), timeUnit)) {
                        try {
                            if (target.tryLock(random.nextInt(10), timeUnit)) {
                                try {
                                    if (origin.getElementCount() >= elementsToSwap) {
                                        origin.removeElements(elementsToSwap);
                                        target.addElements(elementsToSwap);
                                        return true;
                                    } else {
                                        throw new InsufficientElementsException("Insufficient elements to swap.");
                                    }
                                } finally {
                                    target.unlock();
                                }
                            }
                        } finally {
                            origin.unlock();
                        }
                    }
                    Thread.sleep(getFixedDelay() + random.nextInt(getRandomDelay()));
                } catch (InterruptedException | InsufficientElementsException e) {
                    return false;
                }
            }
            return false;
        }

        private int getFixedDelay() {
            return 10;
        }

        private int getRandomDelay() {
            return 20;
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Container containerA = new Container(100);
        Container containerB = new Container(50);

        List<Future<Boolean>> results = new ArrayList<>();

        results.add(executor.submit(new SwapTask(containerA, containerB, 10, 1, TimeUnit.SECONDS)));
