import java.util.Random;

public class SwapProgram {

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Container<Integer> container1 = new Container<>(initializeElements(10));
        Container<Integer> container2 = new Container<>(initializeElements(5));

        executor.submit(() -> performSwap(container1, container2, 5, 1, TimeUnit.SECONDS));
        executor.submit(() -> performSwap(container2, container1, 3, 1, TimeUnit.SECONDS));

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static List<ElementCount<Integer>> initializeElements(int count) {
        List<ElementCount<Integer>> elements = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            elements.add(new ElementCount<>(i, 1));
        }
        return elements;
    }

    private static boolean performSwap(Container<Integer> origin, Container<Integer> target, int elementsToSwap,
                                       long timeout, TimeUnit unit) {
        long timeoutInNanos = unit.toNanos(timeout);
        long endTime = System.nanoTime() + timeoutInNanos;
        Random random = new Random();

        while (System.nanoTime() < endTime) {
            boolean originLockAcquired = false;
            boolean targetLockAcquired = false;
            try {
                originLockAcquired = origin.lock.tryLock(timeoutInNanos, TimeUnit.NANOSECONDS);
                targetLockAcquired = target.lock.tryLock(timeoutInNanos, TimeUnit.NANOSECONDS);

                if (originLockAcquired && targetLockAcquired) {
                    if (origin.getTotalCount() >= elementsToSwap) {
                        origin.removeElements(elementsToSwap);
                        target.addElements(elementsToSwap);
                        System.out.println("Swapped " + elementsToSwap + " elements.");
                        return true;
                    } else {
                        throw new InsufficientElementsException("Not enough elements in the origin container.");
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } catch (InsufficientElementsException e) {
                System.out.println(e.getMessage());
                return false;
            } finally {
                if (originLockAcquired) {
                    origin.lock.unlock();
                }
                if (targetLockAcquired) {
                    target.lock.unlock();
                }
            }

            try {
                TimeUnit.MILLISECONDS.sleep(calculateRandomDelay(random));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return false;
    }

    private static long calculateRandomDelay(Random random) {
        return 50 + random.nextInt(100);
    }

    private static class ElementCount<T> {
        private final T element;
        private final int count;

        public ElementCount(T element, int count) {
            this.element = element;
            this.count = count;
        }
    }

    private static class Container<T> {
        private final Lock lock = new ReentrantLock();
        private final Condition condition = lock.newCondition();
        private List<ElementCount<T>> elements = new ArrayList<>();

        public Container(List<ElementCount<T>> elements) {
            this.elements = elements;
        }

        public int getTotalCount() {
            return elements.size();
        }

        public void removeElements(int count) {
            for (int i = 0; i < count; i++) {
                elements.remove(elements.size() - 1);
            }
            condition.signalAll();
        }

        public void addElements(int count) {
            for (int i = 0; i < count; i++) {
                elements.add(new ElementCount<>(null, 1));
            }
            condition.signalAll();
        }
    }

    private static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }
}
