        if (source.getLock().hashCode() < target.getLock().hashCode()) {
            firstLock = source.getLock();
            secondLock = target.getLock();
        } else {
            firstLock = target.getLock();
            secondLock = source.getLock();
        }

        boolean acquired = false;
        long fixedDelay = 50;
        Random random = new Random();

        try {
            long timeoutInNanos = timeUnit.toNanos(timeout);
            long end = System.nanoTime() + timeoutInNanos;

            while (System.nanoTime() < end) {
                if (firstLock.tryLock(timeoutInNanos, TimeUnit.NANOSECONDS)) {
                    try {
                        if (secondLock.tryLock(timeoutInNanos - (System.nanoTime() - end), TimeUnit.NANOSECONDS)) {
                            try {
                                if (source.getWidgetCount().getCount() >= numberOfWidgets) {
                                    source.getWidgetCount().decrease(numberOfWidgets);
                                    target.getWidgetCount().increase(numberOfWidgets);
                                    System.out.println("Moved " + numberOfWidgets + " widgets from source to target.");
                                    acquired = true;
                                } else {
                                    throw new NotEnoughWidgetsException();
                                }
                            } finally {
                                secondLock.unlock();
                            }
                        }
                    } finally {
                        firstLock.unlock();
                    }
                }

                Thread.sleep(fixedDelay + random.nextInt(100));
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (NotEnoughWidgetsException e) {
            System.out.println("Not enough widgets in source.");
