    public static boolean moveWidgets(Bin srcBin, Bin targetBin, int widgetCount, long timeout, TimeUnit unit) {
        long timeoutInMillis = unit.toMillis(timeout);
        Random random = new Random();
        while (timeoutInMillis > 0) {
            long startTime = System.currentTimeMillis();
            try {
                if (srcBin.lock.tryLock(timeoutInMillis, TimeUnit.MILLISECONDS)) {
                    try {
                        if (targetBin.lock.tryLock(timeoutInMillis, TimeUnit.MILLISECONDS)) {
                            try {
                                if (srcBin.getWidgetCount() >= widgetCount) {
                                    srcBin.removeWidgets(widgetCount);
                                    targetBin.addWidgets(widgetCount);
                                    System.out.println("Moved " + widgetCount + " widgets from source to target bin.");
                                    return true;
                                } else {
                                    System.err.println("Not enough widgets to move.");
                                    throw new NotEnoughWidgetsException("Not enough widgets to move.");
                                }
                            } finally {
                                targetBin.lock.unlock();
                            }
                        }
                    } finally {
                        srcBin.lock.unlock();
                    }
                }
            } catch (InterruptedException | NotEnoughWidgetsException e) {
                Thread.currentThread().interrupt();
                return false;
            }
            long elapsedTime = System.currentTimeMillis() - startTime;
            timeoutInMillis -= elapsedTime;
            try {
                Thread.sleep(calculateRandomPause(random));
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            }
        }
        System.out.println("Could not acquire locks, operation timed out.");
        return false;
    }

    static long calculateRandomPause(Random random) {
        return 50 + random.nextInt(100);
    }

    public static class Bin {
        private int widgetCount;
        private final Lock lock = new ReentrantLock();

        public Bin(int initialCount) {
            this.widgetCount = initialCount;
        }

        public int getWidgetCount() {
            return widgetCount;
        }

        public void removeWidgets(int count) {
            if (widgetCount < count) throw new NotEnoughWidgetsException("Not enough widgets available.");
            widgetCount -= count;
        }

        public void addWidgets(int count) {
            widgetCount += count;
        }
    }

    public static class NotEnoughWidgetsException extends RuntimeException {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }
