public class PersonSetExample {

    public static void main(String[] args) {
        PersonSet personSet = new PersonSet();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable taskAddingPersons = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 5; i++) {
                    Person person = new PersonImpl("Person" + i, i + 20);
                    personSet.addPerson(person);
                    System.out.println("Added: " + person.getName());
                }
            }
        };

        Runnable taskCheckingPersons = new Runnable() {
            @Override
            public void run() {
                for (int i = 0; i < 5; i++) {
                    Person person = new PersonImpl("Person" + i, i + 20);
                    boolean contains = personSet.containsPerson(person);
                    System.out.println("Contains " + person.getName() + ": " + contains);
                }
            }
        };

        executor.submit(taskAddingPersons);
        executor.submit(taskCheckingPersons);

        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
