    public PublishingVehicleTracker(Map<String, SafePoint> locations) {
        this.vehicleLocations = new ConcurrentHashMap<>(locations);
    }

    public Map<String, SafePoint> getVehicleLocations() {
        return Collections.unmodifiableMap(vehicleLocations);
    }

    public SafePoint getVehicleLocation(String vehicleId) {
        SafePoint loc = vehicleLocations.get(vehicleId);
        if (loc == null) {
            throw new IllegalArgumentException("Invalid vehicle ID: " + vehicleId);
        }
        return loc;
    }

    public void updateVehicleLocation(String vehicleId, int x, int y) {
        SafePoint loc = vehicleLocations.get(vehicleId);
        if (loc == null) {
            throw new IllegalArgumentException("Invalid vehicle ID: " + vehicleId);
        }
        loc.set(x, y);
    }

    public static class SafePoint {
        private int x, y;
        private final Lock lock = new ReentrantLock();

