    public PublishingVehicleTracker(Map<String, SafePoint> locations) {
        this.vehicleLocations = new ConcurrentHashMap<>(locations);
    }

    public Map<String, SafePoint> getLocations() {
        lock.readLock().lock();
        try {
            Map<String, SafePoint> result = new HashMap<>();
            for (Map.Entry<String, SafePoint> entry : vehicleLocations.entrySet()) {
                result.put(entry.getKey(), entry.getValue().copy());
            }
            return Collections.unmodifiableMap(result);
        } finally {
            lock.readLock().unlock();
        }
    }

    public SafePoint getLocation(String id) {
        lock.readLock().lock();
        try {
            SafePoint loc = vehicleLocations.get(id);
            if (loc == null) {
                throw new IllegalArgumentException("No such vehicle ID: " + id);
            }
            return loc.copy();
        } finally {
            lock.readLock().unlock();
        }
    }

    public void setLocation(String id, int x, int y) {
        lock.writeLock().lock();
        try {
            SafePoint loc = vehicleLocations.get(id);
            if (loc == null) {
                throw new IllegalArgumentException("No such vehicle ID: " + id);
            }
            loc.set(x, y);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, SafePoint> initialLocations = new ConcurrentHashMap<>();
        initialLocations.put("Vehicle1", new SafePoint(0, 0));
        initialLocations.put("Vehicle2", new SafePoint(10, 10));

        PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialLocations);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> {
