import java.util.concurrent.locks.ReentrantLock;

public class PublishingVehicleTracker {

    private final Map<String, SafePoint> vehicleLocations;
    private final Lock lock = new ReentrantLock();

    public PublishingVehicleTracker(Map<String, SafePoint> initialLocations) {
        this.vehicleLocations = new HashMap<>(initialLocations);
    }

    public Map<String, SafePoint> getVehicleLocations() {
        lock.lock();
        try {
            Map<String, SafePoint> deepCopy = new HashMap<>();
            for (Map.Entry<String, SafePoint> entry : vehicleLocations.entrySet()) {
                deepCopy.put(entry.getKey(), entry.getValue().copy());
            }
            return Collections.unmodifiableMap(deepCopy);
        } finally {
            lock.unlock();
        }
    }

    public SafePoint getLocation(String id) {
        lock.lock();
        try {
            SafePoint loc = vehicleLocations.get(id);
            if (loc == null) {
                throw new IllegalArgumentException("No vehicle found with ID: " + id);
            }
            return loc.copy();
        } finally {
            lock.unlock();
        }
    }

    public void updateLocation(String id, int x, int y) {
        lock.lock();
        try {
            if (!vehicleLocations.containsKey(id)) {
                throw new IllegalArgumentException("No vehicle found with ID: " + id);
            }
            vehicleLocations.get(id).update(x, y);
        } finally {
            lock.unlock();
        }
    }

    private static class SafePoint {
        private int x, y;
        private final Lock pointLock = new ReentrantLock();

        public SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public SafePoint copy() {
            pointLock.lock();
            try {
                return new SafePoint(this.x, this.y);
            } finally {
                pointLock.unlock();
            }
        }

        public void update(int x, int y) {
            pointLock.lock();
            try {
                this.x = x;
                this.y = y;
            } finally {
                pointLock.unlock();
            }
        }

        public int[] getXY() {
            pointLock.lock();
            try {
                return new int[]{x, y};
            } finally {
                pointLock.unlock();
            }
        }
    }

