import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class RunesGrimoire {

    enum Constellation {
        AQUILA, LYRA, TAURUS
    }

    enum Resonance {
        POSITIVE, NEGATIVE
    }

    static class Rune {
        private final Constellation constellation;
        private final Resonance resonance;

        public Rune(Constellation constellation, Resonance resonance) {
            this.constellation = constellation;
            this.resonance = resonance;
        }

        public Constellation getConstellation() {
            return constellation;
        }

        public Resonance getResonance() {
            return resonance;
        }
    }

    static class Harmony {
        private final Rune rune1;
        private final Rune rune2;

        public Harmony(Rune rune1, Rune rune2) {
            this.rune1 = rune1;
            this.rune2 = rune2;
        }
    }

    static class Grimoire {
        private final List<Harmony> harmonies = new ArrayList<>();

        public void crystallize(Harmony harmony) {
            synchronized (harmonies) {
                harmonies.add(harmony);
            }
        }

        public int getHarmonyCount() {
            synchronized (harmonies) {
                return harmonies.size();
            }
        }
    }

    public static int channelTheGrimoire(Collection<Rune> candidateRunes) {
        List<Rune> runes = new ArrayList<>(candidateRunes);
        runes.sort(Comparator.comparing(Rune::getConstellation).thenComparing(Rune::getResonance));

        Grimoire grimoire = new Grimoire();
        ExecutorService executorService = Executors.newFixedThreadPool(2);

        for (int i = 0; i < runes.size() - 1; i++) {
            final int index = i;
            executorService.execute(() -> {
                Rune rune1 = runes.get(index);
                Rune rune2 = runes.get(index + 1);

                if (rune1.getConstellation() == rune2.getConstellation() &&
                    rune1.getResonance() != rune2.getResonance()) {
                    Harmony harmony = new Harmony(rune1, rune2);
                    grimoire.crystallize(harmony);
                }
            });
        }

        executorService.shutdown();
        try {
            executorService.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        return grimoire.getHarmonyCount();
    }

    public static void main(String[] args) {
        List<Rune> candidateRunes = Arrays.asList(
            new Rune(Constellation.AQUILA, Resonance.POSITIVE),
            new Rune(Constellation.AQUILA, Resonance.NEGATIVE),
            new Rune(Constellation.LYRA, Resonance.POSITIVE),
            new Rune(Constellation.LYRA, Resonance.NEGATIVE),
            new Rune(Constellation.TAURUS, Resonance.POSITIVE)
        );

        int harmonyCount = channelTheGrimoire(candidateRunes);
        System.out.println("Total Harmonies: " + harmonyCount);
    }
}

