import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Animals {
private final Ark ark;

public Animals() {
this.ark = new Ark();
}

public int loadTheArk(Collection<Animal> candidates) {
SortedSet<Animal> animals;
int numPairs = 0;
Animal candidate = null;

animals = new TreeSet<>(new SpeciesGenderComparator());
animals.addAll(candidates);
for (Animal a : animals) {
if (candidate == null || !candidate.isPotentialMate(a)) {
candidate = a;
} else {
ark.load(new AnimalPair(candidate, a));
++numPairs;
candidate = null;
}
}
return numPairs;
}

public static void main(String[] args) throws InterruptedException {
Animals animalsApp = new Animals();

Collection<Animal> group1 = createSampleAnimals(4);
Collection<Animal> group2 = createSampleAnimals(4);

ExecutorService executor = Executors.newFixedThreadPool(2);

executor.submit(() -> {
int pairs = animalsApp.loadTheArk(group1);
System.out.println(Thread.currentThread().getName() + " loaded " + pairs + " pairs.");
});

executor.submit(() -> {
int pairs = animalsApp.loadTheArk(group2);
System.out.println(Thread.currentThread().getName() + " loaded " + pairs + " pairs.");
});

executor.shutdown();
}

private static Collection<Animal> createSampleAnimals(int count) {
List<Animal> list = new ArrayList<>();
Random rand = new Random();
Species[] speciesArray = Species.values();
Gender[] genders = Gender.values();

for (int i = 0; i < count; i++) {
Animal animal = new Animal();
animal.species = speciesArray[rand.nextInt(speciesArray.length)];
animal.gender = genders[rand.nextInt(genders.length)];
list.add(animal);
}

return list;
}

static class Animal {
Species species;
Gender gender;

public boolean isPotentialMate(Animal other) {
return species == other.species && gender != other.gender;
}
}

enum Species {
AARDVARK, BENGAL_TIGER, CARIBOU, DINGO
}

enum Gender {
MALE, FEMALE
}

static class AnimalPair {
private final Animal one, two;

public AnimalPair(Animal one, Animal two) {
this.one = one;
this.two = two;
}
}

static class SpeciesGenderComparator implements Comparator<Animal> {
public int compare(Animal one, Animal two) {
int speciesCompare = one.species.compareTo(two.species);
return (speciesCompare != 0)
? speciesCompare
: one.gender.compareTo(two.gender);
}
}

static class Ark {
private final Set<AnimalPair> loadedAnimals = Collections.synchronizedSet(new HashSet<>());

public void load(AnimalPair pair) {
loadedAnimals.add(pair);
System.out.println(Thread.currentThread().getName() + " loaded a pair: " + pair.hashCode());
}
}
}

