import java.util.concurrent.Callable;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class MysticBeastTracker {
    private final ConcurrentHashMap<String, Glyph> beastPerches;

    public MysticBeastTracker(Map<String, Glyph> initialBeasts) {
        this.beastPerches = new ConcurrentHashMap<>(initialBeasts);
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(beastPerches);
    }

    public Glyph getPerch(String sigil) {
        return beastPerches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Glyph newGlyph = new Glyph(spark, glimmer);
        if (beastPerches.replace(sigil, getPerch(sigil), newGlyph) == null) {
            throw new IllegalArgumentException("The beast with sigil " + sigil + " does not exist.");
        }
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(beastPerches));
    }

    public static void main(String[] args) {
        Map<String, Glyph> initialMap = new ConcurrentHashMap<>();
        initialMap.put("Dragon", new Glyph(1, 1));
        initialMap.put("Phoenix", new Glyph(2, 2));

        MysticBeastTracker tracker = new MysticBeastTracker(initialMap);

        ExecutorService executor = Executors.newFixedThreadPool(5);
        Lock lock = new ReentrantLock();

        Callable<Void> task1 = () -> {
            lock.lock();
            try {
                tracker.setPerch("Dragon", 5, 5);
                System.out.println("Dragon perch updated.");
            } finally {
                lock.unlock();
            }
            return null;
        };

        Callable<Void> task2 = () -> {
            lock.lock();
            try {
                tracker.setPerch("Phoenix", 10, 10);
                System.out.println("Phoenix perch updated.");
            } finally {
                lock.unlock();
            }
            return null;
        };

        Callable<Void> task3 = () -> {
            lock.lock();
            try {
                System.out.println("Current Perches: " + tracker.getPerches());
            } finally {
                lock.unlock();
            }
            return null;
        };

        Future<Void> future1 = executor.submit(task1);
        Future<Void> future2 = executor.submit(task2);
        Future<Void> future3 = executor.submit(task3);

        try {
            future1.get();
            future2.get();
            future3.get();
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }
}

