    private final ThreadPoolExecutor executor;

    public CelestialCaravanTracker(Map<String, Starlight> initialHavens) {
        this.beastHavens = new ConcurrentHashMap<>(initialHavens);
        this.executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(5);
    }

