        return Collections.unmodifiableMap(beastHavens);
    }

    public Starlight getHaven(String glyph) {
        return beastHavens.get(glyph);
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        executor.execute(() -> {
            Starlight starlight = beastHavens.computeIfPresent(glyph, (k, v) -> new Starlight(shimmer, pulse));
            if (starlight == null) {
                throw new IllegalArgumentException("Beast with glyph " + glyph + " does not exist.");
            }
        });
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return Collections.unmodifiableMap(beastHavens.entrySet().stream()
            .collect(Collectors.toMap(Map.Entry::getKey, e -> new Starlight(e.getValue().getShimmer(), e.getValue().getPulse()))));
    }

