        private final int shimmer;
        private final int pulse;

        public Starlight(int shimmer, int pulse) {
            this.shimmer = shimmer;
            this.pulse = pulse;
        }

        public int getShimmer() {
            return shimmer;
        }

        public int getPulse() {
            return pulse;
        }

        @Override
        public String toString() {
            return "Starlight{" + "shimmer=" + shimmer + ", pulse=" + pulse + '}';
        }
    }

