        Runnable task1 = () -> tracker.setHaven("Beast-001", 500, 600);
        Runnable task2 = () -> tracker.setHaven("Beast-002", 700, 800);
        Runnable task3 = () -> {
            System.out.println("Current Havens: " + tracker.getHavens());
            System.out.println("Static Havens: " + tracker.getHavensAsStatic());
        };

        List<Runnable> tasks = Arrays.asList(task1, task2, task3);

        tasks.forEach(tracker.executor::execute);

        tracker.executor.shutdown();
        try {
            tracker.executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}

