import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.Collections;
import java.util.Collections;
import java.util.HashMap;
import java.util.Collections;

public class PhantomGliderTracker {

    private final ConcurrentHashMap<String, Nimbus> gliderPerches;

    public PhantomGliderTracker(Map<String, Nimbus> initialPerches) {
        this.gliderPerches = new ConcurrentHashMap<>(initialPerches);
    }

    public Map<String, Nimbus> getPerches() {
        return Collections.unmodifiableMap(gliderPerches);
    }

    public Nimbus getPerch(String rune) {
        return gliderPerches.get(rune);
    }

    public void setPerch(String rune, int glow, int drift) {
        Nimbus newNimbus = new Nimbus(glow, drift);
        Nimbus currentNimbus = gliderPerches.replace(rune, newNimbus);
        if (currentNimbus == null) {
            throw new IllegalArgumentException("Glider with rune " + rune + " does not exist.");
        }
    }

    public Map<String, Nimbus> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(gliderPerches));
    }

    public static void main(String[] args) {
        Map<String, Nimbus> initialMap = new HashMap<>();
        initialMap.put("Aether", new Nimbus(1, 2));
        initialMap.put("Elysium", new Nimbus(3, 4));
        PhantomGliderTracker tracker = new PhantomGliderTracker(initialMap);

        ExecutorService executor = Executors.newFixedThreadPool(5);

        Runnable task1 = () -> {
            System.out.println("Initial Perches: " + tracker.getPerches());
            tracker.setPerch("Aether", 5, 6);
            System.out.println("Updated Perches: " + tracker.getPerchesAsStatic());
        };

        Runnable task2 = () -> {
            Nimbus perch = tracker.getPerch("Elysium");
            System.out.println("Elysium Perch: " + perch);
        };

        Runnable task3 = () -> {
            try {
                tracker.setPerch("Unknown", 7, 8);
            } catch (IllegalArgumentException e) {
                System.out.println(e.getMessage());
            }
        };

        executor.execute(task1);
        executor.execute(task2);
        executor.execute(task3);

        executor.shutdown();
    }
}

class Nimbus {
    private final int glow;
    private final int drift;

    public Nimbus(int glow, int drift) {
        this.glow = glow;
        this.drift = drift;
    }

    @Override
    public String toString() {
        return "Nimbus{" + "glow=" + glow + ", drift=" + drift + '}';
    }
}
