import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class Spellcasting {

    interface Charm {
        void cast();
    }

    interface RuneNode<T> {
        T compute();

        List<RuneNode<T>> getChildRunes();
    }

    public static <T> List<T> processCharmsSequentially(List<Charm> charms) {
        for (Charm charm : charms) {
            charm.cast();
        }
        return new ArrayList<>();
    }

    public static <T> List<T> processCharmsConcurrently(List<Charm> charms) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        for (Charm charm : charms) {
            executor.submit(charm::cast);
        }
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        return new ArrayList<>();
    }

    public static <T> List<T> processRuneTreeSequentially(RuneNode<T> runeNode) {
        List<T> results = new ArrayList<>();
        results.add(runeNode.compute());
        for (RuneNode<T> child : runeNode.getChildRunes()) {
            results.addAll(processRuneTreeSequentially(child));
        }
        return results;
    }

    public static <T> List<T> processRuneTreeConcurrently(RuneNode<T> runeNode) throws InterruptedException, ExecutionException {
        List<T> results = new ArrayList<>();
        ExecutorService executor = Executors.newFixedThreadPool(2);
        results.add(runeNode.compute());
        List<Future<List<T>>> futures = new ArrayList<>();
        for (RuneNode<T> child : runeNode.getChildRunes()) {
            Future<List<T>> future = executor.submit(() -> processRuneTreeConcurrently(child));
            futures.add(future);
        }
        for (Future<List<T>> future : futures) {
            results.addAll(future.get());
        }
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        return results;
    }

    public static void main(String[] args) {
        // Example implementation to demonstrate behavior
        List<Charm> charms = new ArrayList<>();
        charms.add(() -> System.out.println("Charm 1"));
        charms.add(() -> System.out.println("Charm 2"));
        charms.add(() -> System.out.println("Charm 3"));

        try {
            processCharmsSequentially(charms);
            processCharmsConcurrently(charms);
        } catch (InterruptedException | ExecutionException e) {
