import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicInteger;

public class Summoning {

    interface Talisman {
        void activate();
    }

    interface SigilNode {
        int compute();
        List<SigilNode> getChildSigils();
    }

    public static void main(String[] args) {
        List<Talisman> talismans = new ArrayList<>();
        List<SigilNode> sigils = new ArrayList<>();

        // Sequential processing of talismans
        processTalismansSequentially(talismans);

        // Parallel processing of talismans
        processTalismansConcurrently(talismans);

        // Recursive sequential processing of sigils
        AtomicInteger seqResult = new AtomicInteger();
        for (SigilNode rootSigil : sigils) {
            seqResult.addAndGet(processSigilsSequentially(rootSigil));
        }
        System.out.println("Sequential Sigil Total: " + seqResult.get());

        // Recursive parallel processing of sigils
        AtomicInteger parallelResult = new AtomicInteger();
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<Integer>> futures = new ArrayList<>();
        for (SigilNode rootSigil : sigils) {
            futures.add(executor.submit(() -> processSigilsConcurrently(rootSigil, executor)));
        }
        for (Future<Integer> future : futures) {
            try {
                parallelResult.addAndGet(future.get());
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }
        executor.shutdown();
        System.out.println("Parallel Sigil Total: " + parallelResult.get());
    }

    private static void processTalismansSequentially(List<Talisman> talismans) {
        for (Talisman talisman : talismans) {
            talisman.activate();
        }
    }

    private static void processTalismansConcurrently(List<Talisman> talismans) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<Void>> futures = new ArrayList<>();
        for (Talisman talisman : talismans) {
            futures.add(executor.submit(() -> {
                talisman.activate();
                return null;
            }));
        }
        for (Future<Void> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }
        executor.shutdown();
    }

    private static int processSigilsSequentially(SigilNode sigil) {
        int result = sigil.compute();
        for (SigilNode child : sigil.getChildSigils()) {
            result += processSigilsSequentially(child);
        }
        return result;
    }

    private static int processSigilsConcurrently(SigilNode sigil, ExecutorService executor) throws InterruptedException, ExecutionException {
        int result = sigil.compute();
        List<Future<Integer>> futures = new ArrayList<>();
        for (SigilNode child : sigil.getChildSigils()) {
            futures.add(executor.submit(() -> processSigilsConcurrently(child, executor)));
        }
        for (Future<Integer> future : futures) {
