import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class TreasureTransfer {

    public static void main(String[] args) {
        Vault vault1 = new VaultImpl(100);
        Vault vault2 = new VaultImpl(200);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(() -> {
            try {
                Helper.transfer(vault1, vault2, 50);
            } catch (InsufficientTreasureException e) {
                System.out.println(e.getMessage());
            }
        });
        executor.execute(() -> {
            try {
                Helper.transfer(vault2, vault1, 70);
            } catch (InsufficientTreasureException e) {
                System.out.println(e.getMessage());
            }
        });

        executor.shutdown();
    }

    interface Vault {
        GoldAmount getGoldAmount();
        void debit(int amount) throws InsufficientTreasureException;
        void credit(int amount);
    }

    interface GoldAmount {
        int getAmount();
    }

    static class VaultImpl implements Vault {
        private final GoldAmount goldAmount;
        private final Lock lock = new ReentrantLock();

        public VaultImpl(int initialAmount) {
            this.goldAmount = new GoldAmountImpl(initialAmount);
        }

        public GoldAmount getGoldAmount() {
            return goldAmount;
        }

        public void debit(int amount) throws InsufficientTreasureException {
            lock.lock();
            try {
                if (goldAmount.getAmount() < amount) {
                    throw new InsufficientTreasureException("Insufficient treasure in vault");
                }
                ((GoldAmountImpl) goldAmount).decrement(amount);
            } finally {
                lock.unlock();
            }
        }

        public void credit(int amount) {
            lock.lock();
            try {
                ((GoldAmountImpl) goldAmount).increment(amount);
            } finally {
                lock.unlock();
            }
        }

        private class GoldAmountImpl implements GoldAmount {
            private int amount;

            public GoldAmountImpl(int amount) {
                this.amount = amount;
            }

            public int getAmount() {
                return amount;
            }

            public void decrement(int amount) {
                this.amount -= amount;
            }

            public void increment(int amount) {
                this.amount += amount;
            }
        }
    }

    static class Helper {
        private static final Lock tieLock = new ReentrantLock();

        public static void transfer(Vault fromVault, Vault toVault, int amount) throws InsufficientTreasureException {
            Vault firstLock = fromVault;
            Vault secondLock = toVault;

            int fromHash = System.identityHashCode(fromVault);
            int toHash = System.identityHashCode(toVault);

            if (fromHash == toHash) {
                tieLock.lock();
                try {
                    if (fromVault.getGoldAmount().getAmount() >= amount) {
                        internalTransfer(fromVault, toVault, amount);
                    }
                } finally {
                    tieLock.unlock();
                }
            } else {
                if (fromHash > toHash) {
                    firstLock = toVault;
                    secondLock = fromVault;
                }
                synchronized (firstLock) {
                    synchronized (secondLock) {
                        if (fromVault.getGoldAmount().getAmount() >= amount) {
                            internalTransfer(fromVault, toVault, amount);
                        }
                    }
                }
            }
        }

        private static void internalTransfer(Vault fromVault, Vault toVault, int amount) throws InsufficientTreasureException {
            fromVault.debit(amount);
            toVault.credit(amount);
        }
    }

    static class InsufficientTreasureException extends Exception {
        public InsufficientTreasureException(String message) {
            super(message);
        }
    }
}

