import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class GemTransferProgram {

    public static void main(String[] args) {
        Hoard hoard1 = new GemHoard(100);
        Hoard hoard2 = new GemHoard(50);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(() -> performGemTransfer(hoard1, hoard2, new GemAmountImpl(30)));
        executor.execute(() -> performGemTransfer(hoard2, hoard1, new GemAmountImpl(20)));

        executor.shutdown();
    }

    private static void performGemTransfer(Hoard from, Hoard to, GemAmount amount) {
        Hoard firstLock = from;
        Hoard secondLock = to;

        int fromHash = System.identityHashCode(from);
        int toHash = System.identityHashCode(to);

        if (fromHash > toHash) {
            firstLock = to;
            secondLock = from;
        } else if (fromHash == toHash) {
            Lock globalTieLock = new ReentrantLock();
            globalTieLock.lock();
            try {
                initiateTransfer(from, to, amount);
            } finally {
                globalTieLock.unlock();
            }
            return;
        }

        synchronized (firstLock) {
            synchronized (secondLock) {
                initiateTransfer(from, to, amount);
            }
        }
    }

    private static void initiateTransfer(Hoard from, Hoard to, GemAmount amount) {
        TransferHelper helper = new TransferHelper();
        try {
            helper.transfer(from, to, amount);
            System.out.println("Transfer successful: " + amount.getAmount() + 
                               " gem(s) from Hoard " + from + " to Hoard " + to);
        } catch (InsufficientGemsException e) {
            System.out.println("Transfer failed: " + e.getMessage());
        }
    }

    interface Hoard {
        int getGems();
        void addGems(int amount);
        void removeGems(int amount) throws InsufficientGemsException;
    }

    static class GemHoard implements Hoard {
        private int gems;
        private final Lock lock = new ReentrantLock();

        GemHoard(int initialGems) {
            this.gems = initialGems;
        }

        @Override
        public int getGems() {
            return gems;
        }

        @Override
        public void addGems(int amount) {
            lock.lock();
            try {
                gems += amount;
            } finally {
                lock.unlock();
            }
        }

        @Override
        public void removeGems(int amount) throws InsufficientGemsException {
            lock.lock();
            try {
                if (gems < amount) throw new InsufficientGemsException("Not enough gems to transfer");
                gems -= amount;
            } finally {
                lock.unlock();
            }
        }

        @Override
        public String toString() {
            return String.valueOf(System.identityHashCode(this));
        }
    }

    interface GemAmount {
        int getAmount();
    }

    static class GemAmountImpl implements GemAmount {
        private final int amount;

        GemAmountImpl(int amount) {
            this.amount = amount;
        }

        @Override
        public int getAmount() {
            return amount;
        }
    }

    static class TransferHelper {
        void transfer(Hoard from, Hoard to, GemAmount amount) throws InsufficientGemsException {
            from.removeGems(amount.getAmount());
            to.addGems(amount.getAmount());
        }
    }

    static class InsufficientGemsException extends Exception {
        InsufficientGemsException(String message) {
            super(message);
        }
    }
}

