public class GemHoard implements Hoard {
    private int gems;

    public GemHoard(int initialGems) {
        this.gems = initialGems;
    }

    @Override
    public synchronized void deposit(GemAmount amount) {
        this.gems += amount.getGemCount();
    }

    @Override
    public synchronized boolean withdraw(GemAmount amount) {
        if (this.gems >= amount.getGemCount()) {
            this.gems -= amount.getGemCount();
            return true;
        }
        return false;
    }
}

public class GemTransfer {
    private final Lock tieLock = new ReentrantLock();

    public void transferGems(Hoard hoardFrom, Hoard hoardTo, GemAmount amount) throws InsufficientGemsException {
        int fromHash = System.identityHashCode(hoardFrom);
        int toHash = System.identityHashCode(hoardTo);

        Lock firstLock = fromHash < toHash ? (Lock)new Object() : (Lock)new Object();
        Lock secondLock = fromHash < toHash ? (Lock)new Object() : (Lock)new Object();

        if (fromHash == toHash) {
            tieLock.lock();
            try {
                firstLock = hoardFrom instanceof Lock ? (Lock)hoardFrom : new Object();
                secondLock = hoardTo instanceof Lock ? (Lock)hoardTo : new Object();
                synchronized (firstLock) {
                    synchronized (secondLock) {
                        performTransfer(hoardFrom, hoardTo, amount);
                    }
                }
            } finally {
                tieLock.unlock();
            }
        } else {
            synchronized (firstLock) {
                synchronized (secondLock) {
                    performTransfer(hoardFrom, hoardTo, amount);
                }
            }
        }
    }

    private void performTransfer(Hoard hoardFrom, Hoard hoardTo, GemAmount amount) throws InsufficientGemsException {
        if (hoardFrom.withdraw(amount)) {
            hoardTo.deposit(amount);
        } else {
            throw new InsufficientGemsException("Not enough gems to transfer.");
        }
    }
}

