import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class CrystalTransferProgram {

    interface VaultNode {
        int getCrystals();
        void withdrawCrystals(int amount) throws InsufficientCrystalsException;
        void depositCrystals(int amount);
    }

    interface CrystalAmount {
        int getAmount();
    }

    static class InsufficientCrystalsException extends Exception {
        public InsufficientCrystalsException(String message) {
            super(message);
        }
    }

    static class Vault implements VaultNode {
        private int crystals;
        private final Lock lock = new ReentrantLock();

        public Vault(int initialCrystals) {
            this.crystals = initialCrystals;
        }

        @Override
        public synchronized int getCrystals() {
            return crystals;
        }

        @Override
        public void withdrawCrystals(int amount) throws InsufficientCrystalsException {
            if (crystals < amount) {
                throw new InsufficientCrystalsException("Not enough crystals");
            }
            crystals -= amount;
        }

        @Override
        public void depositCrystals(int amount) {
            crystals += amount;
        }

        public Lock getLock() {
            return lock;
        }
    }

    static class CrystalTransferHelper {
        private final Lock tieBreakerLock = new ReentrantLock();

        public void transferCrystals(VaultNode from, VaultNode to, CrystalAmount amount) throws InsufficientCrystalsException {
            VaultNode first = from;
            VaultNode second = to;
            if (System.identityHashCode(from) > System.identityHashCode(to)) {
                first = to;
                second = from;
            }

            Lock firstLock = (first instanceof Vault) ? ((Vault) first).getLock() : tieBreakerLock;
            Lock secondLock = (second instanceof Vault) ? ((Vault) second).getLock() : tieBreakerLock;

            firstLock.lock();
            try {
                secondLock.lock();
                try {
                    from.withdrawCrystals(amount.getAmount());
                    to.depositCrystals(amount.getAmount());
                } finally {
                    secondLock.unlock();
                }
            } finally {
                firstLock.unlock();
            }
        }
    }

    static class FixedCrystalAmount implements CrystalAmount {
        private final int amount;

        public FixedCrystalAmount(int amount) {
            this.amount = amount;
        }

        @Override
        public int getAmount() {
            return amount;
        }
    }

    public static void main(String[] args) {
        Vault vaultA = new Vault(100);
        Vault vaultB = new Vault(200);
        CrystalAmount transferAmount = new FixedCrystalAmount(50);
        CrystalTransferHelper helper = new CrystalTransferHelper();

        Runnable transferTask = () -> {
            try {
                helper.transferCrystals(vaultA, vaultB, transferAmount);
                System.out.println("Transfer successful: VaultA = " + vaultA.getCrystals() + ", VaultB = " + vaultB.getCrystals());
            } catch (InsufficientCrystalsException e) {
                System.out.println(e.getMessage());
            }
        };

        ExecutorService executorService = Executors.newFixedThreadPool(2);
        executorService.execute(transferTask);
        executorService.execute(transferTask);
        executorService.shutdown();
    }
}

