import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

public class MagicalOrbVault {

    private static class Orb {
        private final String name;

        public Orb(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return this.name;
        }
    }

    private static class CircularVault {
        private final Orb[] vault;
        private int head, tail;
        private final Semaphore availableOrbs;
        private final Semaphore availableSlots;
        private final Object lock = new Object();

        public CircularVault(int capacity) {
            vault = new Orb[capacity];
            this.head = 0;
            this.tail = 0;
            this.availableOrbs = new Semaphore(0);
            this.availableSlots = new Semaphore(capacity);
        }

        public void put(Orb x) throws InterruptedException {
            availableSlots.acquire();
            synchronized (lock) {
                vault[tail] = x;
                tail = (tail + 1) % vault.length;
            }
            availableOrbs.release();
        }

        public Orb take() throws InterruptedException {
            availableOrbs.acquire();
            Orb orb;
            synchronized (lock) {
                orb = vault[head];
                head = (head + 1) % vault.length;
            }
            availableSlots.release();
            return orb;
        }

        public boolean isEmpty() {
            return availableOrbs.availablePermits() == 0;
        }

        public boolean isFull() {
            return availableSlots.availablePermits() == 0;
        }
    }

    public static void main(String[] args) {
        final CircularVault vault = new CircularVault(5);
        Runnable sorcererA = () -> {
            try {
