import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

public class MagicalOrbVault {
    private final int capacity;
    private final Orb[] vault;
    private int head = 0;
    private int tail = 0;
    private final Semaphore filledSlots;
    private final Semaphore emptySlots;
    private final Object lock = new Object();

    public MagicalOrbVault(int capacity) {
        this.capacity = capacity;
        this.vault = new Orb[capacity];
        this.filledSlots = new Semaphore(0);
        this.emptySlots = new Semaphore(capacity);
    }

    public void put(Orb orb) throws InterruptedException {
        emptySlots.acquire();
        synchronized (lock) {
            vault[tail] = orb;
            tail = (tail + 1) % capacity;
        }
        filledSlots.release();
    }

    public Orb take() throws InterruptedException {
        filledSlots.acquire();
        Orb orb;
        synchronized (lock) {
            orb = vault[head];
            head = (head + 1) % capacity;
        }
        emptySlots.release();
        return orb;
    }

    public boolean isEmpty() {
        return filledSlots.availablePermits() == 0;
    }

    public boolean isFull() {
        return emptySlots.availablePermits() == 0;
    }

    public static class Orb {
        private final String name;

        public Orb(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return "Orb{" + "name='" + name + '\'' + '}';
        }
    }

    public static void main(String[] args) {
        MagicalOrbVault vault = new MagicalOrbVault(5);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    vault.put(new Orb("Orb" + i));
                    System.out.println("Placed: Orb" + i);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.execute(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    Orb orb = vault.take();
                    System.out.println("Took: " + orb);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
    }
}

