import java.util.Queue;

public class OrbVault {

    private final Queue<Orb> vault;
    private final Semaphore orbs;
    private final Semaphore slots;
    private final Object lock = new Object();
    private final int capacity;

    public OrbVault(int capacity) {
        this.capacity = capacity;
        this.vault = new LinkedList<>();
        this.orbs = new Semaphore(0);
        this.slots = new Semaphore(capacity);
    }

    public void put(Orb x) throws InterruptedException {
        slots.acquire();
        synchronized (lock) {
            vault.add(x);
        }
        orbs.release();
