        Map<String, String> initialRelics = new HashMap<>();
        initialRelics.put("Excalibur", "Sword of King Arthur");
        CrystalCache<String, String> cache = new CrystalCache<>(initialRelics);

        ExecutorService executor = Executors.newFixedThreadPool(3);

