import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;

public class DragonTrackerApp {
    public static void main(String[] args) {
        Map<String, MutableOrb> initialConstellation = new HashMap<>();
        initialConstellation.put("Dragon1", new MutableOrb(0, 0));
        initialConstellation.put("Dragon2", new MutableOrb(10, 10));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initialConstellation);

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        executorService.execute(() -> {
            tracker.setOrb("Dragon1", 5, 5);
            MutableOrb orb = tracker.getOrb("Dragon1");
            if (orb != null) {
                System.out.println("Updated Dragon1 Location: " + orb);
            }
        });

        executorService.execute(() -> {
            tracker.setOrb("Dragon2", 15, 15);
            MutableOrb orb = tracker.getOrb("Dragon2");
            if (orb != null) {
                System.out.println("Updated Dragon2 Location: " + orb);
            }
        });

        Map<String, MutableOrb> constellations = tracker.getConstellations();
        constellations.forEach((key, value) -> System.out.println("Constellation Key: " + key + ", Location: " + value));

        executorService.shutdown();
    }
}

class MutableOrb {
    private int x, y;

    public MutableOrb(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public MutableOrb(MutableOrb other) {
        this.x = other.x;
        this.y = other.y;
    }

    public void setCoordinates(int x, int y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public String toString() {
        return "Shimmer(" + x + ", " + y + ")";
    }
}

class ChronomanticDragonTracker {
    private final Map<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Map<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(this.constellation));
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = constellation.get(sigil);
        return orb == null ? null : new MutableOrb(orb);
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        MutableOrb orb = constellation.get(sigil);
        if (orb == null) {
            throw new IllegalArgumentException("Sigil not found in constellation: " + sigil);
        }
        orb.setCoordinates(shimmerX, shimmerY);
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> original) {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : original.entrySet()) {
            copy.put(entry.getKey(), new MutableOrb(entry.getValue()));
        }
        return copy;
    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ChronomanticDragonTracker {
    private final Map<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Map<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> original) {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : original.entrySet()) {
            copy.put(entry.getKey(), new MutableOrb(entry.getValue().getX(), entry.getValue().getY()));
        }
        return copy;
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(this.constellation));
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = this.constellation.get(sigil);
        return orb != null ? new MutableOrb(orb.getX(), orb.getY()) : null;
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        if (!this.constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found");
        }
        this.constellation.put(sigil, new MutableOrb(shimmerX, shimmerY));
    }

    public static void main(String[] args) throws Exception {
        Map<String, MutableOrb> initialConstellation = new HashMap<>();
        initialConstellation.put("DragonA", new MutableOrb(10, 20));
        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initialConstellation);

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        Runnable getConstellationsTask = () -> {
            Map<String, MutableOrb> constellations = tracker.getConstellations();
            System.out.println("Constellations: " + constellations);
        };

        Runnable setOrbTask = () -> {
            tracker.setOrb("DragonA", 30, 40);
            System.out.println("Updated DragonA");
        };

        Future<?> future1 = executorService.submit(getConstellationsTask);
        Future<?> future2 = executorService.submit(setOrbTask);

        future1.get();
        future2.get();

        executorService.shutdown();
    }
}

