    public ChronomanticDragonTracker(Map<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> source) {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : source.entrySet()) {
            copy.put(entry.getKey(), new MutableOrb(entry.getValue().getShimmerX(), entry.getValue().getShimmerY()));
        }
        return copy;
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(this.constellation));
    }

