        MutableOrb orb = this.constellation.get(sigil);
        return orb != null ? new MutableOrb(orb.getShimmerX(), orb.getShimmerY()) : null;
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        MutableOrb orb = this.constellation.get(sigil);
        if (orb != null) {
            orb.setShimmerX(shimmerX);
            orb.setShimmerY(shimmerY);
        } else {
            throw new IllegalArgumentException("Sigil not found: " + sigil);
        }
