import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class SummonChaosOrbs {

    static class ManaShard {
        private int amount;

        public ManaShard(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    static class Orb {
        private int mana;
        private final Lock lock = new ReentrantLock();

        public Orb(int initialMana) {
            this.mana = initialMana;
        }

        public boolean lock() {
            return lock.tryLock();
        }

        public void unlock() {
            lock.unlock();
        }

        public void addMana(int amount) {
            mana += amount;
        }

        public void removeMana(int amount) throws InsufficientManaException {
            if (mana < amount) {
                throw new InsufficientManaException();
            }
            mana -= amount;
        }

        public int getMana() {
            return mana;
        }
    }

    static class InsufficientManaException extends Exception {
    }

    static class EtherealFlux {
        public static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InsufficientManaException {
            boolean fromLocked = false;
            boolean toLocked = false;
            try {
                fromLocked = from.lock();
                toLocked = to.lock();
                if (fromLocked && toLocked) {
                    from.removeMana(amount.getAmount());
                    to.addMana(amount.getAmount());
                }
            } finally {
                if (toLocked) to.unlock();
                if (fromLocked) from.unlock();
            }
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random;

        public FluxThread(Orb[] orbs) {
            this.orbs = orbs;
            this.random = new Random();
        }

        @Override
        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex = random.nextInt(orbs.length);
                int toIndex = random.nextInt(orbs.length);
                while (toIndex == fromIndex) {
                    toIndex = random.nextInt(orbs.length);
                }
                Orb from = orbs[fromIndex];
                Orb to = orbs[toIndex];
                ManaShard shard = new ManaShard(random.nextInt(10) + 1);
                try {
                    EtherealFlux.transferEnergy(from, to, shard);
                } catch (InsufficientManaException ignored) {
                }
            }
        }
    }

    public static void main(String[] args) {
        Orb[] orbs = new Orb[5];
        for (int i = 0; i < orbs.length; i++) {
            orbs[i] = new Orb(100);
        }

        FluxThread thread1 = new FluxThread(orbs);
        FluxThread thread2 = new FluxThread(orbs);

        thread1.start();
        thread2.start();

        try {
            thread1.join();
            thread2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        for (int i = 0; i < orbs.length; i++) {
            System.out.println("Orb " + i + " mana: " + orbs[i].getMana());
        }
    }
}

