public class SummonChaosOrbs {

    static class Orb {
        private final Lock lock = new ReentrantLock();
        private int mana = 100;

        public void lock() {
            lock.lock();
        }

        public void unlock() {
            lock.unlock();
        }

        public int getMana() {
            return mana;
        }

        public void addMana(int amount) {
            mana += amount;
        }

        public void subtractMana(int amount) throws InsufficientManaException {
            if (mana < amount) {
                throw new InsufficientManaException("Not enough mana");
            }
            mana -= amount;
        }
    }

    static class EtherealFlux {
        public static void transferEnergy(Orb from, Orb to, int amount) throws InsufficientManaException {
            from.lock();
            to.lock();
            try {
                from.subtractMana(amount);
                to.addMana(amount);
            } finally {
                from.unlock();
                to.unlock();
            }
        }
    }

    static class InsufficientManaException extends Exception {
        public InsufficientManaException(String message) {
            super(message);
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random = new Random();

        public FluxThread(Orb[] orbs) {
            this.orbs = orbs;
        }

        @Override
        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex = random.nextInt(orbs.length);
                int toIndex = random.nextInt(orbs.length);
                if (fromIndex != toIndex) {
                    int amount = random.nextInt(10) + 1;
                    try {
                        EtherealFlux.transferEnergy(orbs[fromIndex], orbs[toIndex], amount);
                    } catch (InsufficientManaException e) {
                        // Exception is ignored as required
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        int numberOfOrbs = 5;
        int numberOfThreads = 2;
        Orb[] orbs = new Orb[numberOfOrbs];

        for (int i = 0; i < numberOfOrbs; i++) {
            orbs[i] = new Orb();
        }

        Thread[] threads = new Thread[numberOfThreads];
        for (int i = 0; i < numberOfThreads; i++) {
            threads[i] = new FluxThread(orbs);
            threads[i].start();
        }

        for (Thread thread : threads) {
