import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class GoblinGoldShuffle {
    private static final int NUM_POUCHES = 5;
    private static final int NUM_THREADS = 2;
    private static final int NUM_ITERATIONS = 10;
    private static final int INITIAL_GOLD = 100;

    public static void main(String[] args) {
        GoblinPouch[] pouches = new GoblinPouch[NUM_POUCHES];
        for (int i = 0; i < NUM_POUCHES; i++) {
            pouches[i] = new GoblinPouch(INITIAL_GOLD);
        }

        TradeThread[] threads = new TradeThread[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; i++) {
            threads[i] = new TradeThread(pouches);
            threads[i].start();
        }

        for (TradeThread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    static class GoblinPouch {
        private final Lock lock = new ReentrantLock();
        private int goldAmount;

        public GoblinPouch(int goldAmount) {
            this.goldAmount = goldAmount;
        }

        public void addGold(int amount) {
            this.goldAmount += amount;
        }

        public void removeGold(int amount) throws InsufficientGoldException {
            if (amount > goldAmount) {
                throw new InsufficientGoldException("Not enough gold.");
            }
            this.goldAmount -= amount;
        }

        public Lock getLock() {
            return lock;
        }

        public int getGoldAmount() {
            return goldAmount;
        }
    }

    static class GoldClump {
        private final int amount;

        public GoldClump(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    static class SneakyTrade {
        public static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            Lock firstLock = from.getLock();
            Lock secondLock = to.getLock();

            while (true) {
                boolean gotFirst = false, gotSecond = false;
                try {
                    gotFirst = firstLock.tryLock();
                    gotSecond = secondLock.tryLock();

                    if (gotFirst && gotSecond) {
                        from.removeGold(amount.getAmount());
                        to.addGold(amount.getAmount());
                        break;
                    }
                } finally {
                    if (gotFirst) firstLock.unlock();
                    if (gotSecond) secondLock.unlock();
                }
            }
        }
    }

    static class InsufficientGoldException extends Exception {
        public InsufficientGoldException(String message) {
            super(message);
        }
    }

    static class TradeThread extends Thread {
        private final GoblinPouch[] pouches;
        private final Random random = new Random();

        public TradeThread(GoblinPouch[] pouches) {
            this.pouches = pouches;
        }

        @Override
        public void run() {
            for (int i = 0; i < NUM_ITERATIONS; i++) {
                int fromIndex = random.nextInt(pouches.length);
                int toIndex = random.nextInt(pouches.length);
                while (fromIndex == toIndex) {
                    toIndex = random.nextInt(pouches.length);
                }

                GoblinPouch fromPouch = pouches[fromIndex];
                GoblinPouch toPouch = pouches[toIndex];

                int maxTransferAmount = fromPouch.getGoldAmount();
                if (maxTransferAmount > 0) {
                    int transferAmount = random.nextInt(maxTransferAmount) + 1;
                    GoldClump clump = new GoldClump(transferAmount);

                    try {
                        SneakyTrade.transferGold(fromPouch, toPouch, clump);
                    } catch (InsufficientGoldException e) {
                        // Exception ignored as per requirements
                    }
                }
            }
        }
    }
}
