import java.util.concurrent.Executors;

public class CelestialHourglass implements Runnable {

    private volatile boolean activated = false;
    private long dawnTime = 0;
    private long duskTime = 0;

    @Override
    public synchronized void run() {
        long currentChronon = System.nanoTime();
        if (!activated) {
            activated = true;
            dawnTime = currentChronon;
        } else {
            duskTime = currentChronon;
        }
    }

    public synchronized void reset() {
        activated = false;
        dawnTime = 0;
        duskTime = 0;
    }

    public synchronized long getFlow() {
        return duskTime - dawnTime;
    }

