        private final ReentrantLock lock = new ReentrantLock();

        public Account(String id, DollarAmount balance) {
            this.id = id;
            this.balance = balance;
        }

        public DollarAmount getBalance() {
            return balance;
        }

        public void deposit(DollarAmount amount) {
            balance = balance.add(amount);
        }

        public void withdraw(DollarAmount amount) throws InsufficientFundsException {
            if (balance.compareTo(amount) < 0) {
                throw new InsufficientFundsException("Insufficient funds");
            }
            balance = balance.subtract(amount);
        }

        public boolean lock(long timeout, TimeUnit unit) throws InterruptedException {
            return lock.tryLock(timeout, unit);
        }

        public void unlock() {
