public class DeadlockAvoidance {

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Account accountA = new Account(new DollarAmount(1000));
        Account accountB = new Account(new DollarAmount(1000));

        Runnable transferTask1 = () -> {
            try {
                boolean success = transferMoney(accountA, accountB, new DollarAmount(100), 3, TimeUnit.SECONDS);
                if (success) {
                    System.out.println("Transfer from A to B successful");
                } else {
                    System.out.println("Transfer from A to B failed due to timeout");
                }
            } catch (InsufficientFundsException e) {
                System.out.println("Transfer from A to B failed due to insufficient funds");
            }
        };

        Runnable transferTask2 = () -> {
            try {
                boolean success = transferMoney(accountB, accountA, new DollarAmount(500), 3, TimeUnit.SECONDS);
                if (success) {
                    System.out.println("Transfer from B to A successful");
                } else {
                    System.out.println("Transfer from B to A failed due to timeout");
                }
            } catch (InsufficientFundsException e) {
                System.out.println("Transfer from B to A failed due to insufficient funds");
            }
        };

        executor.execute(transferTask1);
        executor.execute(transferTask2);

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }

    static Random random = new Random();

    public static boolean transferMoney(Account source, Account destination, DollarAmount amount, long timeout, TimeUnit unit) throws InsufficientFundsException {
        long fixedDelay = 50;
        long randMod = 100;
        long stopTime = System.nanoTime() + unit.toNanos(timeout);

        while (System.nanoTime() < stopTime) {
            if (acquireLocks(source.lock, destination.lock, timeout, unit)) {
                try {
                    if (source.getBalance().compareTo(amount) < 0) {
                        throw new InsufficientFundsException();
                    } else {
                        source.debit(amount);
                        destination.credit(amount);
                        return true;
                    }
                } finally {
                    source.lock.unlock();
                    destination.lock.unlock();
                }
            }
            try {
                Thread.sleep(fixedDelay + random.nextLong() % randMod);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        return false;
    }

    private static boolean acquireLocks(Lock lock1, Lock lock2, long timeout, TimeUnit unit) {
        boolean gotFirstLock = false;
        boolean gotSecondLock = false;
        long stopTime = System.nanoTime() + unit.toNanos(timeout);

        try {
            while (System.nanoTime() < stopTime) {
                try {
                    gotFirstLock = lock1.tryLock(timeout, unit);
                    if (gotFirstLock) {
                        gotSecondLock = lock2.tryLock(timeout, unit);
                        if (gotSecondLock) {
                            return true;
                        } else {
                            lock1.unlock();
                            gotFirstLock = false;
                        }
                    }
                } catch (InterruptedException ignored) {
                }
                Thread.sleep(10 + random.nextLong() % 50);
            }
        } catch (InterruptedException ignored) {
        } finally {
            if (gotFirstLock) lock1.unlock();
            if (gotSecondLock) lock2.unlock();
        }
        return false;
    }

