import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConcurrentApp {

    public static class MyAppThread extends Thread {
        private static final String DEFAULT_NAME = "MyAppThread";
        private static final AtomicInteger uniqueNumber = new AtomicInteger(1);
        private static final AtomicInteger created = new AtomicInteger(0);
        private static final AtomicInteger alive = new AtomicInteger(0);
        private static final Logger logger = Logger.getLogger(MyAppThread.class.getName());
        private static volatile boolean debugLifecycle = false;

        public MyAppThread(Runnable target) {
            super(target, DEFAULT_NAME + "-" + uniqueNumber.getAndIncrement());
            setUncaughtExceptionHandler((t, e) -> 
                logger.log(Level.SEVERE, "Thread " + t.getName() + " terminated with exception: ", e));
        }

        @Override
        public void run() {
            boolean debug = debugLifecycle;
            if (debug) logger.info("Created " + getName());
            created.incrementAndGet();
            alive.incrementAndGet();
            try {
                super.run();
            } finally {
                alive.decrementAndGet();
                if (debug) logger.info("Exiting " + getName());
            }
        }

        public static int getCreated() {
            return created.get();
        }

        public static int getAlive() {
            return alive.get();
        }

        public static void setDebug(boolean debug) {
            debugLifecycle = debug;
        }
    }

    public static void main(String[] args) {
        MyAppThread.setDebug(true);

        Runnable task = () -> {
            String threadName = Thread.currentThread().getName();
            try {
                System.out.println("Running task in " + threadName);
                if (Math.random() > 0.5)
