                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        System.out.println("Total threads created: " + MyAppThread.getCreated());
        System.out.println("Currently alive threads: " + MyAppThread.getAlive());
    }
}

