import java.util.concurrent.TimeUnit;

public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, Point> locations;

    public DelegatingVehicleTracker(Map<String, Point> points) {
        this.locations = new ConcurrentHashMap<>(points);
    }

    public Map<String, Point> getLocations() {
        return Collections.unmodifiableMap(locations);
    }

    public Point getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        Point point = locations.get(id);
        if (point == null) {
            throw new IllegalArgumentException("No such vehicle: " + id);
        }
        locations.put(id, new Point(x, y));
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(locations));
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Map<String, Point> initialLocations = Map.of(
            "vehicle1", new Point(0, 0),
            "vehicle2", new Point(10, 10),
            "vehicle3", new Point(20, 20)
        );

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);
        ExecutorService executorService = Executors.newFixedThreadPool(5);

        Runnable readLocations = () -> {
            System.out.println("All locations: " + tracker.getLocationsAsStatic());
        };

        Callable<String> updateLocation = () -> {
            tracker.setLocation("vehicle1", 5, 5);
            return "Updated vehicle1 location";
        };

        Future<String> futureUpdate = executorService.submit(updateLocation);
        executorService.execute(readLocations);

        System.out.println(futureUpdate.get());
        executorService.execute(readLocations);

        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }
}

import java.util.*;
