public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, Point> locations;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.locations = new ConcurrentHashMap<>(initialLocations);
    }

    public Map<String, Point> getLocations() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public Point getLocation(String id) {
        lock.readLock().lock();
        try {
            return locations.get(id);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void setLocation(String id, int x, int y) {
        lock.writeLock().lock();
        try {
            Point loc = locations.get(id);
            if (loc == null)
                throw new IllegalArgumentException("Invalid vehicle ID: " + id);
            locations.put(id, new Point(x, y));
        } finally {
            lock.writeLock().unlock();
        }
    }

    public Map<String, Point> getLocationsAsStatic() {
        lock.readLock().lock();
        try {
            return Collections.unmodifiableMap(new HashMap<>(locations));
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, Point> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", new Point(0, 0));
        initialLocations.put("vehicle2", new Point(5, 5));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

        ExecutorService executorService = Executors.newFixedThreadPool(5);

        Runnable readTask = () -> {
            System.out.println(Thread.currentThread().getName() + " - Locations: " + tracker.getLocations());
            System.out.println(Thread.currentThread().getName() + " - Static Locations: " + tracker.getLocationsAsStatic());
        };

        Runnable writeTask = () -> {
            tracker.setLocation("vehicle1", new Random().nextInt(100), new Random().nextInt(100));
            System.out.println(Thread.currentThread().getName() + " - Updated vehicle1 location.");
        };

        for (int i = 0; i < 3; i++) {
            executorService.submit(readTask);
        }

        for (int i = 0; i < 2; i++) {
            executorService.submit(writeTask);
        }

        executorService.shutdown();
        try {
            executorService.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

