public class DemonstrateDeadlock {

    public static void main(String[] args) {
        final int NUM_ACCOUNTS = 5;
        final int NUM_THREADS = 2;
        final int TRANSFER_ITERATIONS = 10;

        Account[] accounts = new Account[NUM_ACCOUNTS];
        for (int i = 0; i < accounts.length; i++) {
            accounts[i] = new Account(1000); // Initialize each account with 1000 units
        }

        Thread[] threads = new Thread[NUM_THREADS];
        for (int i = 0; i < threads.length; i++) {
            threads[i] = new TransferThread(accounts, TRANSFER_ITERATIONS);
            threads[i].start();
        }

        for (Thread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    static class DollarAmount {
        private final int amount;

        DollarAmount(int amount) {
            this.amount = amount;
        }

        int getAmount() {
            return amount;
        }
    }

    static class InsufficientFundsException extends Exception {
    }

    static class Account {
        private int balance;
        private final ReentrantLock lock = new ReentrantLock();

        Account(int initialBalance) {
            this.balance = initialBalance;
        }

        void debit(DollarAmount d) throws InsufficientFundsException {
            if (balance < d.getAmount()) throw new InsufficientFundsException();
            balance -= d.getAmount();
        }

        void credit(DollarAmount d) {
            balance += d.getAmount();
        }

        ReentrantLock getLock() {
            return lock;
        }
    }

    static class DynamicOrderDeadlock {
        public static void transferMoney(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
            Account firstLock = from.hashCode() < to.hashCode() ? from : to;
            Account secondLock = from.hashCode() < to.hashCode() ? to : from;

            firstLock.getLock().lock();
            try {
                secondLock.getLock().lock();
                try {
                    from.debit(amount);
                    to.credit(amount);
                } finally {
                    secondLock.getLock().unlock();
                }
            } finally {
                firstLock.getLock().unlock();
            }
        }
    }

    static class TransferThread extends Thread {
        private final Account[] accounts;
        private final int iterations;
        private final Random random = new Random();

        TransferThread(Account[] accounts, int iterations) {
            this.accounts = accounts;
            this.iterations = iterations;
        }

