import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StripedMap {
    private static final int N_LOCKS = 16;
    private final Node[] buckets;
    private final Lock[] locks;

    public StripedMap(int numBuckets) {
        buckets = new Node[numBuckets];
        locks = new Lock[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new ReentrantLock();
        }
    }

    private static class Node {
        final int key;
        int value;
        Node next;

        Node(int key, int value, Node next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    private int hash(int key) {
        return key % buckets.length;
    }

    public void put(int key, int value) {
        int index = hash(key);
        int lockIndex = index % N_LOCKS;
        locks[lockIndex].lock();
        try {
            Node node = buckets[index];
            if (node == null) {
                buckets[index] = new Node(key, value, null);
            } else {
                while (node.next != null && node.key != key) {
                    node = node.next;
                }
                if (node.key == key) {
                    node.value = value;
                } else {
                    node.next = new Node(key, value, null);
                }
            }
        } finally {
            locks[lockIndex].unlock();
        }
    }

    public Integer get(int key) {
        int index = hash(key);
        int lockIndex = index % N_LOCKS;
        locks[lockIndex].lock();
        try {
            Node node = buckets[index];
            while (node != null) {
                if (node.key == key) {
                    return node.value;
                }
                node = node.next;
            }
            return null;
        } finally {
            locks[lockIndex].unlock();
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            int lockIndex = i % N_LOCKS;
            locks[lockIndex].lock();
            try {
                buckets[i] = null;
            } finally {
                locks[lockIndex].unlock();
            }
        }
    }

    public static void main(String[] args) {
        StripedMap map = new StripedMap(32);
        ExecutorService executor = Executors.newFixedThreadPool(4);

        Runnable task1 = () -> {
            for (int i = 0; i < 50; i++) {
                map.put(i, i * 10);
            }
        };

        Runnable task2 = () -> {
            for (int i = 0; i < 50; i++) {
                System.out.println("Get: " + map.get(i));
            }
        };

        Runnable task3 = () -> map.clear();

        executor.execute(task1);
        executor.execute(task2);
        executor.execute(task3);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("Map operations completed.");
    }
}

