import java.math.BigInteger;
import java.util.Arrays;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ConcurrentImmutableCache {

    private final BigInteger number;
    private final BigInteger[] factors;

    public ConcurrentImmutableCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = factors.clone();
    }

    public BigInteger[] getFactors(BigInteger inputNumber) {
        if (this.number.equals(inputNumber)) {
            return factors.clone();
        }
        return null;
    }

    private static BigInteger[] calculateFactors(BigInteger number) {
        BigInteger[] tempFactors = new BigInteger[number.intValue()];
        int index = 0;
        for (BigInteger i = BigInteger.ONE; i.compareTo(number) <= 0; i = i.add(BigInteger.ONE)) {
            if (number.mod(i).equals(BigInteger.ZERO)) {
                tempFactors[index++] = i;
            }
        }
        return Arrays.copyOf(tempFactors, index);
    }

    public static void main(String[] args) throws Exception {
        BigInteger numberToCache = new BigInteger("28");

        ExecutorService executor = Executors.newFixedThreadPool(2);
