        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }

    private static class CacheTask implements Callable<ImmutableCache> {
        private final ImmutableCache cache;
        private final BigInteger number;

        CacheTask(ImmutableCache cache, BigInteger number) {
            this.cache = cache;
            this.number = number;
        }

        @Override
        public ImmutableCache call() {
            BigInteger[] factors = computeFactors(number);
            return new ImmutableCache(number, factors);
        }
    }

    private static class FactorTask implements Callable<BigInteger[]> {
        private final ImmutableCache cache;
        private final BigInteger number;

        FactorTask(ImmutableCache cache, BigInteger number) {
            this.cache = cache;
            this.number = number;
        }

        @Override
        public BigInteger[] call() {
            return cache.getFactors(number);
        }
    }

