            this.number = number;
            this.factors = Arrays.copyOf(factors, factors.length);
        }

        public BigInteger[] getFactors(BigInteger num) {
            if (num.equals(number)) {
                return Arrays.copyOf(factors, factors.length);
            }
            return null;
        }

        public BigInteger getNumber() {
            return this.number;
        }
    }

    private static BigInteger[] computeFactors(BigInteger number) {
        BigInteger two = BigInteger.valueOf(2);
        BigInteger zero = BigInteger.ZERO;
        List<BigInteger> factorList = new java.util.ArrayList<>();
        BigInteger n = number;

        for (BigInteger i = BigInteger.ONE; i.compareTo(n.sqrt()) <= 0; i = i.add(BigInteger.ONE)) {
            if (n.mod(i).equals(zero)) {
                factorList.add(i);
                if (!i.equals(n.divide(i))) {
                    factorList.add(n.divide(i));
                }
            }
        }

        return factorList.toArray(new BigInteger[0]);
    }
}

