            printFactors(result2.get());
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executorService.shutdown();
        }
    }

    private static void printFactors(BigInteger[] factors) {
        if (factors == null) {
            System.out.println("No cached factors found.");
        } else {
            System.out.println("Factors: " + Arrays.toString(factors));
        }
    }

    private static BigInteger[] calculateFactors(BigInteger number) {
        return number.isProbablePrime(1) ? new BigInteger[]{number}
                : Arrays.stream(new BigInteger(number.toString()).divideAndRemainder(new BigInteger("2")))
                .filter(n -> number.mod(n).equals(BigInteger.ZERO)).toArray(BigInteger[]::new);
    }

    public static final class ImmutableCache {
        private final BigInteger number;
        private final BigInteger[] factors;

        public ImmutableCache(BigInteger number, BigInteger[] factors) {
            this.number = number;
            this.factors = factors.clone();
        }

        public BigInteger[] getFactors(BigInteger number) {
            if (this.number.equals(number)) {
                return factors.clone();
            }
            return null;
        }
    }
}

