import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MonitorVehicleTracker {

    private final Map<String, MutablePoint> vehicleLocations;

    public MonitorVehicleTracker(Map<String, MutablePoint> locations) {
        this.vehicleLocations = deepCopy(locations);
    }

    public synchronized Map<String, MutablePoint> getLocations() {
        return deepCopy(vehicleLocations);
    }

    public synchronized MutablePoint getLocation(String id) {
        MutablePoint p = vehicleLocations.get(id);
        if (p == null) return null;
        return new MutablePoint(p);
    }

    public synchronized void setLocation(String id, int x, int y) {
        MutablePoint loc = vehicleLocations.get(id);
        if (loc == null) throw new IllegalArgumentException("Invalid vehicle ID: " + id);
        loc.x = x;
        loc.y = y;
    }

    private static Map<String, MutablePoint> deepCopy(Map<String, MutablePoint> m) {
        Map<String, MutablePoint> result = new HashMap<>();
        for (Map.Entry<String, MutablePoint> e : m.entrySet()) {
            result.put(e.getKey(), new MutablePoint(e.getValue()));
        }
        return Collections.unmodifiableMap(result);
    }

