import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicReference;

public class NonBlockingStack<T> {

    private static class Node<T> {
        private final T item;
        private final Node<T> next;

        Node(T item, Node<T> next) {
            this.item = item;
            this.next = next;
        }
    }

    private final AtomicReference<Node<T>> top = new AtomicReference<>(null);

    public void push(T item) {
        Node<T> newNode = new Node<>(item, null);
        while (true) {
            Node<T> currentTop = top.get();
            newNode.next = currentTop;
            if (top.compareAndSet(currentTop, newNode)) {
                break;
            }
        }
    }

    public T pop() {
        while (true) {
            Node<T> currentTop = top.get();
            if (currentTop == null) continue; // Retry if empty
            if (top.compareAndSet(currentTop, currentTop.next)) {
                return currentTop.item;
            }
        }
    }

    public static void main(String[] args) {
        NonBlockingStack<Integer> stack = new NonBlockingStack<>();
        ExecutorService executor = Executors.newFixedThreadPool(3);

