import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DelegatingVehicleTracker {

    private final ConcurrentHashMap<String, Point> vehicleLocations;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.vehicleLocations = new ConcurrentHashMap<>(initialLocations);
    }

    public Point getLocation(String vehicleId) {
        return vehicleLocations.get(vehicleId);
    }

    public void setLocation(String vehicleId, int x, int y) {
        if (vehicleLocations.replace(vehicleId, new Point(x, y)) == null) {
            System.err.println("Vehicle ID not found: " + vehicleId);
        }
    }

    public Map<String, Point> getLocationsLiveView() {
        // Return an unmodifiable view that's backed by the concurrent map
        return Collections.unmodifiableMap(vehicleLocations);
    }

    public Map<String, Point> getLocationsSnapshot() {
        // Return a copy of the current state as an unmodifiable map
        return Collections.unmodifiableMap(new HashMap<>(vehicleLocations));
    }

    private static class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
