import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class ArkLoader {

    enum Gender { MALE, FEMALE }

    class Animal {
        private final String species;
        private final Gender gender;

        Animal(String species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }

        public String getSpecies() {
            return species;
        }

        public Gender getGender() {
            return gender;
        }
    }

    class AnimalPair {
        private final Animal male;
        private final Animal female;

        AnimalPair(Animal male, Animal female) {
            this.male = male;
            this.female = female;
        }

        @Override
        public String toString() {
            return "(" + male.getSpecies() + ": " + male.getGender() + ", " + female.getGender() + ")";
        }
    }

    class Ark {
        private final List<AnimalPair> animalPairs = new ArrayList<>();

        public void addPair(AnimalPair pair) {
            animalPairs.add(pair);
        }

        public int getPairCount() {
            return animalPairs.size();
        }

        public List<AnimalPair> getAnimalPairs() {
            return animalPairs;
        }
    }

    private int loadTheArk(Collection<Animal> candidates, ExecutorService executor) throws InterruptedException {
        List<Animal> sortedAnimals = new ArrayList<>(candidates);
        sortedAnimals.sort(Comparator.comparing(Animal::getSpecies).thenComparing(Animal::getGender));

        Map<String, Queue<Animal>> speciesMap = sortedAnimals.stream()
                .collect(Collectors.groupingBy(
                        Animal::getSpecies,
                        Collectors.toCollection(LinkedList::new)
                ));

        Ark ark = new Ark();
        List<Runnable> tasks = new ArrayList<>();

        for (Map.Entry<String, Queue<Animal>> entry : speciesMap.entrySet()) {
            tasks.add(() -> {
                Queue<Animal> queue = entry.getValue();
                while (queue.size() >= 2) {
                    Animal first = queue.poll();
                    Animal second = queue.peek();

                    if (first.getGender() != second.getGender()) {
                        queue.poll();
                        AnimalPair pair = new AnimalPair(first, second);
                        synchronized (ark) {
                            ark.addPair(pair);
                        }
                    } else {
                        queue.offer(first);
                    }
                }
            });
        }

        List<Future<?>> futures = tasks.stream().map(executor::submit).collect(Collectors.toList());
        for (Future<?> future : futures) {
            future.get();
        }

        return ark.getPairCount();
    }

    public static void main(String[] args) {
        ArkLoader arkLoader = new ArkLoader();
        List<Animal> candidates = Arrays.asList(
                arkLoader.new Animal("Elephant", Gender.MALE),
                arkLoader.new Animal("Elephant", Gender.FEMALE),
                arkLoader.new Animal("Tiger", Gender.FEMALE),
                arkLoader.new Animal("Tiger", Gender.MALE),
                arkLoader.new Animal("Lion", Gender.MALE),
                arkLoader.new Animal("Lion", Gender.MALE),
                arkLoader.new Animal("Lion", Gender.FEMALE)
        );

        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            int pairs = arkLoader.loadTheArk(candidates, executor);
            System.out.println("Total pairs formed: " + pairs);
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
    }
}

