        ThreadSafeMutableInteger mutableInteger = new ThreadSafeMutableInteger();

        Runnable incrementTask = () -> {
            for (int i = 0; i < 1000; i++) {
                synchronized (mutableInteger) {
                    int currentValue = mutableInteger.getValue();
                    mutableInteger.setValue(currentValue + 1);
                }
            }
