import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.math.BigInteger;
import java.util.concurrent.TimeUnit;

public class PrimeProducerConsumer {

    private static final int QUEUE_CAPACITY = 10;
    private static final int NUM_PRIMES = 20;

    public static void main(String[] args) {
        BlockingQueue<BigInteger> queue = new LinkedBlockingQueue<>(QUEUE_CAPACITY);

        PrimeProducer producer = new PrimeProducer(queue, NUM_PRIMES);
        PrimeConsumer consumer = new PrimeConsumer(queue, NUM_PRIMES);

        producer.start();
        consumer.start();

        try {
            consumer.join();
            producer.interrupt();
            producer.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static class PrimeProducer extends Thread {
        private final BlockingQueue<BigInteger> queue;
        private final int numPrimes;

        PrimeProducer(BlockingQueue<BigInteger> queue, int numPrimes) {
            this.queue = queue;
            this.numPrimes = numPrimes;
        }

        public void run() {
            try {
                BigInteger prime = BigInteger.ONE;
                for (int i = 0; i < numPrimes && !Thread.currentThread().isInterrupted(); i++) {
                    prime = prime.nextProbablePrime();
                    queue.put(prime);
                }
            } catch (InterruptedException ignore) {
                Thread.currentThread().interrupt();
            }
        }
    }

    static class PrimeConsumer extends Thread {
        private final BlockingQueue<BigInteger> queue;
        private final int numPrimes;

        PrimeConsumer(BlockingQueue<BigInteger> queue, int numPrimes) {
            this.queue = queue;
            this.numPrimes = numPrimes;
        }

        public void run() {
            try {
                for (int i = 0; i < numPrimes; i++) {
                    BigInteger prime = queue.poll(Long.MAX_VALUE, TimeUnit.SECONDS);
                    if (prime != null) {
                        System.out.println(prime);
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

