this.queue = queue;
this.maxPrimesToGenerate = maxPrimesToGenerate;
}

@Override
public void run() {
try {
BigInteger p = BigInteger.ONE;
int count = 0;
while (!Thread.currentThread().isInterrupted() && count < maxPrimesToGenerate) {
p = p.nextProbablePrime();
queue.put(p);
count++;
}
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
}

public void cancel() {
interrupt();
}

public static void main(String[] args) throws InterruptedException {
BlockingQueue<BigInteger> queue = new LinkedBlockingQueue<>();
final int primesToProduce = 2;

