import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class PublishingVehicleTracker {
    private final Map<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableMap;

    public PublishingVehicleTracker(Map<String, SafePoint> points) {
        this.locations = new HashMap<>(points);
        this.unmodifiableMap = Collections.unmodifiableMap(locations);
    }

    public Map<String, SafePoint> getLocations() {
        Map<String, SafePoint> result = new HashMap<>();
        for (Map.Entry<String, SafePoint> entry : unmodifiableMap.entrySet()) {
            result.put(entry.getKey(), entry.getValue());
        }
        return Collections.unmodifiableMap(result);
    }

    public SafePoint getLocation(String id) {
        SafePoint loc = locations.get(id);
        if (loc == null) {
            throw new IllegalArgumentException("No such ID: " + id);
        }
        return loc;
    }

    public void setLocation(String id, int x, int y) {
        SafePoint loc = locations.get(id);
        if (loc == null) {
            throw new IllegalArgumentException("No such ID: " + id);
        }
        loc.set(x, y);
    }

    public static void main(String[] args) {
        Map<String, SafePoint> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", new SafePoint(10, 10));
        initialLocations.put("vehicle2", new SafePoint(20, 20));

        PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialLocations);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            tracker.setLocation("vehicle1", 30, 30);
            SafePoint sp1 = tracker.getLocation("vehicle1");
            System.out.println("Vehicle1: " + sp1);
        });

        executor.submit(() -> {
            tracker.setLocation("vehicle2", 40, 40);
            SafePoint sp2 = tracker.getLocation("vehicle2");
            System.out.println("Vehicle2: " + sp2);
        });

        executor.shutdown();
    }
}

class SafePoint {
