import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class PublishingVehicleTracker {

    private final Map<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableMap;
    private final Lock lock = new ReentrantLock();

    public PublishingVehicleTracker(Map<String, SafePoint> points) {
        this.locations = new HashMap<>(points);
        this.unmodifiableMap = Collections.unmodifiableMap(locations);
    }

    public Map<String, SafePoint> getLocations() {
        lock.lock();
        try {
            return unmodifiableMap;
        } finally {
            lock.unlock();
        }
    }

    public SafePoint getLocation(String id) {
        lock.lock();
        try {
            SafePoint loc = locations.get(id);
            if (loc == null) {
                throw new IllegalArgumentException("Invalid vehicle ID: " + id);
            }
            return loc;
        } finally {
            lock.unlock();
        }
    }

    public void setLocation(String id, int x, int y) {
        lock.lock();
        try {
            SafePoint loc = locations.get(id);
            if (loc == null) {
                throw new IllegalArgumentException("Invalid vehicle ID: " + id);
            }
            loc.set(x, y);
        } finally {
            lock.unlock();
        }
    }

    public static class SafePoint {
        private int x, y;
        private final Lock lock = new ReentrantLock();

        public SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public SafePoint(SafePoint p) {
            this(p.getX(), p.getY());
        }

        public int getX() {
            lock.lock();
            try {
                return x;
            } finally {
                lock.unlock();
            }
        }

        public int getY() {
            lock.lock();
            try {
                return y;
            } finally {
                lock.unlock();
            }
        }

        public void set(int x, int y) {
            lock.lock();
            try {
                this.x = x;
                this.y = y;
            } finally {
                lock.unlock();
            }
        }
    }

    public static void main(String[] args) {
        Map<String, SafePoint> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", new SafePoint(10, 15));
        initialLocations.put("vehicle2", new SafePoint(23, 42));

        PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialLocations);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> {
            try {
                tracker.setLocation("vehicle1", 20, 25);
                SafePoint loc = tracker.getLocation("vehicle1");
                System.out.println("Updated location of vehicle1: (" + loc.getX() + ", " + loc.getY() + ")");
            } catch (Exception e) {
                System.out.println(e.getMessage());
            }
