import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.atomic.AtomicInteger;

interface Element<T> {
    T compute();
}

interface Node<T> extends Element<T> {
    List<Node<T>> getChildren();
}

class SequentialProcessor {
    public static <T> List<T> process(List<Element<T>> elements) {
        List<T> result = new ArrayList<>();
        for (Element<T> element : elements) {
            result.add(element.compute());
        }
        return result;
    }

    public static <T> List<T> traverse(Node<T> node) {
        List<T> result = new ArrayList<>();
        result.add(node.compute());
        for (Node<T> child : node.getChildren()) {
            result.addAll(traverse(child));
        }
        return result;
    }
}

class ParallelProcessor {
    public static <T> List<T> process(List<Element<T>> elements) {
        ExecutorService executor = Executors.newFixedThreadPool(1);
        List<Future<T>> futures = new ArrayList<>();
        for (Element<T> element : elements) {
            futures.add(executor.submit(() -> element.compute()));
        }
        List<T> results = collectResults(futures);
        executor.shutdown();
        return results;
    }

    public static <T> List<T> traverse(Node<T> node) {
        ExecutorService executor = Executors.newFixedThreadPool(1);
        List<T> results = Collections.synchronizedList(new ArrayList<>());
        AtomicInteger pendingTasks = new AtomicInteger(1);
        traverseNode(node, executor, results, pendingTasks);

        synchronized (results) {
            while (pendingTasks.get() > 0) {
                try {
                    results.wait();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        executor.shutdown();
        return results;
    }

    private static <T> void traverseNode(Node<T> node, ExecutorService executor, List<T> results, AtomicInteger pendingTasks) {
        executor.submit(() -> {
            results.add(node.compute());
            List<Node<T>> children = node.getChildren();
            pendingTasks.addAndGet(children.size());
            for (Node<T> child : children) {
                traverseNode(child, executor, results, pendingTasks);
            }
            if (pendingTasks.decrementAndGet() == 0) {
                synchronized (results) {
                    results.notifyAll();
                }
            }
        });
    }

    private static <T> List<T> collectResults(List<Future<T>> futures) {
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }
        return results;
    }
}

public class ConcurrentExample {
    public static void main(String[] args) {
        // Define some test elements and nodes
        List<Element<Integer>> elements = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            int value = i;
            elements.add(() -> value);
        }

        Node<Integer> root = new SimpleNode<>(1, new SimpleNode<>(2), new SimpleNode<>(3, new SimpleNode<>(4)));

        // Sequential processing
        List<Integer> seqElementResults = SequentialProcessor.process(elements);
        List<Integer> seqNodeResults = SequentialProcessor.traverse(root);

        // Parallel processing
        List<Integer> parElementResults = ParallelProcessor.process(elements);
        List<Integer> parNodeResults = ParallelProcessor.traverse(root);

        // Output results
        System.out.println("Sequential Element Results: " + seqElementResults);
        System.out.println("Sequential Node Results: " + seqNodeResults);

        System.out.println("Parallel Element Results: " + parElementResults);
        System.out.println("Parallel Node Results: " + parNodeResults);
    }
}

class SimpleNode<T> implements Node<T> {
    private final T value;
    private final List<Node<T>> children;

    @SafeVarargs
    public SimpleNode(T value, Node<T>... children) {
        this.value = value;
        this.children = new ArrayList<>();
        Collections.addAll(this.children, children);
    }

    @Override
    public T compute() {
        return value;
    }

    @Override
    public List<Node<T>> getChildren() {
        return children;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class ConcurrentProcessing {

    public interface Element {
        void process();
    }

    public interface Node {
        void compute();

        List<Node> getChildren();
    }

    public void processSequentially(List<Element> elements) {
        for (Element element : elements) {
            element.process();
        }
    }

    public void processConcurrently(List<Element> elements) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<?>> futures = new ArrayList<>();
        for (Element element : elements) {
            futures.add(executor.submit(() -> element.process()));
        }
        for (Future<?> future : futures) {
            future.get();
        }
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }

    public void processSequentiallyRecursive(Node node) {
        node.compute();
        for (Node child : node.getChildren()) {
            processSequentiallyRecursive(child);
        }
    }

    public void processConcurrentlyRecursive(Node node, ExecutorService executor) throws InterruptedException, ExecutionException {
        List<Callable<Void>> tasks = new ArrayList<>();
        tasks.add(() -> {
            node.compute();
            return null;
        });
        List<Future<Void>> futures = executor.invokeAll(tasks);
        for (Future<Void> future : futures) {
            future.get();
        }
        for (Node child : node.getChildren()) {
            processConcurrentlyRecursive(child, executor);
        }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ConcurrentProcessing cp = new ConcurrentProcessing();
        List<Element> elements = new ArrayList<>();

        Node treeRoot = new Node() {
            @Override
            public void compute() {
            }

            @Override
            public List<Node> getChildren() {
                return new ArrayList<>();
            }
        };

        // Sequential Processing
        cp.processSequentially(elements);
        cp.processSequentiallyRecursive(treeRoot);

        // Concurrent Processing
        cp.processConcurrently(elements);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            cp.processConcurrentlyRecursive(treeRoot, executor);
        } finally {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.MINUTES);
        }
    }
}

import java.util.ArrayList;
