import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

interface Element {
    Object compute();
}

class BasicElement implements Element {
    private final int value;

    public BasicElement(int value) {
        this.value = value;
    }

    @Override
    public Integer compute() {
        return value * value;
    }
}

interface Node<E extends Element> {
    E compute();
    List<Node<E>> getChildren();
}

class TreeNode<E extends Element> implements Node<E> {
    private final E element;
    private final List<Node<E>> children;

    public TreeNode(E element) {
        this.element = element;
        this.children = new ArrayList<>();
    }

    public void addChild(Node<E> child) {
        children.add(child);
    }

    @Override
    public E compute() {
        return element;
    }

    @Override
    public List<Node<E>> getChildren() {
        return children;
    }
}

public class ConcurrentProcessing {

    public static <E extends Element> List<Object> sequentialProcessing(List<E> elements) {
        List<Object> result = new ArrayList<>();
        for (E element : elements) {
            result.add(element.compute());
        }
        return result;
    }

    public static <E extends Element> List<Object> parallelProcessing(ExecutorService executor, List<E> elements) 
            throws InterruptedException, ExecutionException {
        List<Callable<Object>> tasks = new ArrayList<>();
        for (E element : elements) {
            tasks.add(element::compute);
        }
        List<Future<Object>> futures = executor.invokeAll(tasks);
        List<Object> result = new ArrayList<>();
        for (Future<Object> future : futures) {
            result.add(future.get());
        }
        return result;
    }

    public static <E extends Element> List<Object> recursiveSequential(Node<E> node) {
        List<Object> result = new ArrayList<>();
        result.add(node.compute().compute());
        for (Node<E> child : node.getChildren()) {
            result.addAll(recursiveSequential(child));
        }
        return result;
    }

    public static <E extends Element> List<Object> recursiveParallel(ExecutorService executor, Node<E> node) 
            throws InterruptedException, ExecutionException {
        List<Callable<Object>> tasks = new ArrayList<>();
        tasks.add(node.compute()::compute);
        List<Object> result = new ArrayList<>();
        List<Future<Object>> futures = executor.invokeAll(tasks);
        for (Future<Object> future : futures) {
            result.add(future.get());
        }
        for (Node<E> child : node.getChildren()) {
            result.addAll(recursiveParallel(executor, child));
        }
        return result;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<BasicElement> list = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            list.add(new BasicElement(i));
        }

        System.out.println("Sequential List Processing: " + sequentialProcessing(list));
        System.out.println("Parallel List Processing: " + parallelProcessing(executor, list));

        TreeNode<BasicElement> root = new TreeNode<>(new BasicElement(1));
        TreeNode<BasicElement> child1 = new TreeNode<>(new BasicElement(2));
        TreeNode<BasicElement> child2 = new TreeNode<>(new BasicElement(3));
        root.addChild(child1);
        root.addChild(child2);

        System.out.println("Recursive Sequential Tree Processing: " + recursiveSequential(root));
        System.out.println("Recursive Parallel Tree Processing: " + recursiveParallel(executor, root));

        executor.shutdown();
    }
}

