            System.out.println("Map size: " + rwMap.size());
        };

        Runnable writeTask = () -> {
            rwMap.put(1, "Thread-Safe");
            rwMap.put(2, "ReadWriteMap");
        };

        executor.submit(readTask);
        executor.submit(writeTask);
        executor.submit(readTask);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
