import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private final ReentrantReadWriteLock.ReadLock readLock = lock.readLock();
    private final ReentrantReadWriteLock.WriteLock writeLock = lock.writeLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V get(K key) {
        readLock.lock();
        try {
            return map.get(key);
        } finally {
            readLock.unlock();
        }
    }

    public V put(K key, V value) {
        writeLock.lock();
        try {
            return map.put(key, value);
        } finally {
            writeLock.unlock();
        }
    }

    public V remove(K key) {
        writeLock.lock();
        try {
            return map.remove(key);
        } finally {
            writeLock.unlock();
        }
    }

    public boolean containsKey(K key) {
        readLock.lock();
        try {
            return map.containsKey(key);
        } finally {
            readLock.unlock();
        }
    }

    public boolean containsValue(V value) {
        readLock.lock();
        try {
            return map.containsValue(value);
        } finally {
            readLock.unlock();
        }
    }

    public int size() {
        readLock.lock();
        try {
            return map.size();
        } finally {
            readLock.unlock();
        }
    }

    public boolean isEmpty() {
        readLock.lock();
        try {
            return map.isEmpty();
        } finally {
            readLock.unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, Integer> originalMap = new HashMap<>();
        ReadWriteMap<String, Integer> readWriteMap = new ReadWriteMap<>(originalMap);

        ExecutorService executorService = Executors.newFixedThreadPool(3);

        Runnable writerTask = () -> {
            for (int i = 0; i < 5; i++) {
                readWriteMap.put("key" + i, i);
                System.out.println("Put: key" + i + " -> " + i);
            }
        };

        Runnable readerTask = () -> {
            for (int i = 0; i < 5; i++) {
                Integer value = readWriteMap.get("key" + i);
                System.out.println("Got: key" + i + " -> " + value);
            }
        };

        executorService.submit(writerTask);
        executorService.submit(readerTask);
        executorService.submit(readerTask);

        executorService.shutdown();
    }
}

